ns.ClassQuestInfo = {
    [26] = { n = "A Lesson to Learn", cn = "必修的课程", l = 16, r = 16, f = "A", races = { 4, 95 }, s = { { 4217, "玛斯雷·驭熊者", "达纳苏斯", 35.2, 8, 1457 } }, e = { 11802, "德迪利特·星焰", "月光林地", 56.2, 30.4, 1450 }, note = "16 级后可直接向职业训练师学习水栖形态，本链改为可选；想拿链奖励或体验流程再做，月光林地传送回去接后续最方便。" },
    [27] = { n = "A Lesson to Learn", cn = "必修的课程", l = 16, r = 16, f = "H", races = { 6, 96 }, s = { { 3033, "图拉克·符文图腾", "雷霆崖", 76.4, 27.6, 1456 } }, e = { 11802, "德迪利特·星焰", "月光林地", 56.2, 30.4, 1450 }, note = "16 级可接：联盟在达纳苏斯找玛弗雷恩·熊皮，部落在雷霆崖找图拉克·图腾；水栖形态现已可向训练师直接习得，本链为可选，做完仍不影响形态使用。" },
    [28] = { n = "Trial of the Lake", cn = "湖中试炼", l = 16, r = 16, f = "H", races = { 6, 96 }, s = { { 11802, "德迪利特·星焰", "月光林地", 56.2, 30.4, 1450 } }, e = { 11799, "塔加里", "月光林地", 36.4, 40.2, 1450 }, note = "潜入月光林地南面的月神圣殿湖，水下气泡裂缝约在 (51,51)，也有玩家报 (55,53)；面向东北游过水下山丘，底部的瓶状容器即目标，为固定刷新点。" },
    [29] = { n = "Trial of the Lake", cn = "湖中试炼", l = 16, r = 16, f = "A", races = { 4, 95 }, s = { { 11802, "德迪利特·星焰", "月光林地", 56.2, 30.4, 1450 } }, e = { 11799, "塔加里", "月光林地", 36.4, 40.2, 1450 }, note = "部落版流程与联盟相同：潜入湖中找气泡裂缝，瓶状容器固定刷新（有玩家报在 (47,47)）；取回护符后走到巨型山羊人雕像旁的树下，站进雕像正后方右键使用即可完成。" },
    [30] = { n = "Trial of the Sea Lion", cn = "海狮试炼", l = 16, r = 16, f = "H", races = { 6, 96 }, s = { { 11799, "塔加里", "月光林地", 36.4, 40.2, 1450 } }, e = { 11802, "德迪利特·星焰", "月光林地", 56.2, 30.4, 1450 }, note = "半程试炼需在两处水域各取一件饰品：联盟为黑海岸约 (48,11) 与西部荒野约 (17,33)，部落为贫瘠之地约 (56,8) 与银松森林约 (29,29)；水下没有地图标记，注意憋气，中途死亡会以幽灵状态复活在十字路口。" },
    [31] = { n = "Aquatic Form", cn = "水栖形态", l = 16, r = 16, f = "H", races = { 6, 96 }, s = { { 11802, "德迪利特·星焰", "月光林地", 56.2, 30.4, 1450 } }, e = { 3033, "图拉克·符文图腾", "雷霆崖", 76.4, 27.6, 1456 }, items = { 16608, 263411 }, spells = { 1066 }, note = "交付后获得水栖形态：游泳速度提升且水下无限呼吸；不适合当战斗形态，但潜水换气与战场河道里非常实用。" },
    [63] = { n = "Call of Water", cn = "水之召唤", l = 23, r = 20, f = "H", races = { 2, 6, 8, 96 }, s = { { 5901, "水之先知伊斯伦", "贫瘠之地", 65.8, 43.8, 1413 } }, e = { 113791, "神器任务进度", "银松森林", 38.2, 44.5, 1421 }, note = "到银松森林神龛约 (38,44)，在神龛前使用药剂，击败一只可攻击的元素后点燃火盆，与现身的水元素对话即完成；从墓穴旅馆后绕过大树往下跳是最快的路线，返回时沿海岸向北绕山走。" },
    [96] = { n = "Call of Water", cn = "水之召唤", l = 23, r = 20, f = "H", races = { 2, 6, 8, 96 }, s = { { 5895, "水之魂", "银松森林", 38.6, 44.6, 1421 } }, e = { 5901, "水之先知伊斯伦", "贫瘠之地", 65.8, 43.8, 1413 }, items = { 5177 }, spells = { 5394 }, note = "跨地图跑腿任务：按提示先后在十字路口与塔伦米尔交接，最后到约 (66,44) 交付；沿途无需刻意杀怪，交完两个任务就能推进到终点。" },
    [100] = { n = "Call of Water", cn = "水之召唤", l = 23, r = 20, f = "H", races = { 2, 6, 8, 96 }, s = { { 113791, "神器任务进度", "银松森林", 38.2, 44.5, 1421 } }, e = { 5895, "水之魂", "银松森林", 38.6, 44.6, 1421 }, note = "失败不用慌，可找身后巨魔重接（需再回棘齿城一趟）；神龛无法从墓穴方向直接进入，需沿海岸线绕行，或从旅馆后的大树跳下去。" },
    [220] = { n = "Call of Water", cn = "水之召唤", l = 23, r = 20, f = "H", races = { 2, 6, 8, 96 }, s = { { 5899, "布瑞恩", "贫瘠之地", 43.4, 77.4, 1413 } }, e = { 5901, "水之先知伊斯伦", "贫瘠之地", 65.8, 43.8, 1413 }, items = { 6637 } },
    [272] = { n = "Trial of the Sea Lion", cn = "海狮试炼", l = 16, r = 16, f = "A", races = { 4, 95 }, s = { { 11799, "塔加里", "月光林地", 36.4, 40.2, 1450 } }, e = { 11802, "德迪利特·星焰", "月光林地", 56.2, 30.4, 1450 }, note = "联盟半程：黑海岸约 (48,11) 与西部荒野约 (17,33) 两处水下各取一件饰品；黑海岸水下深水巨兽较多，西部荒野那件在礁石交汇处的水底箱子里，两件都拿到再去月光林地交付。" },
    [335] = { n = "A Noble Brew", cn = "名酿", l = 30, r = 25, f = "A", s = { { 1435, "黑爪加尔德斯", "暴风城", 26.4, 78.4, 1453 } }, e = { 1435, "黑爪加尔德斯", "暴风城", 26.4, 78.4, 1453 }, note = "蒂洛亚之泪在暮色森林庄园篱笆内、斯塔尔万房子旁的小花束（约 78,36），不太起眼；麝香根草在湿地湖边约 (65,75)。" },
    [336] = { n = "A Noble Brew", cn = "名酿", l = 30, r = 25, f = "A", s = { { 1435, "黑爪加尔德斯", "暴风城", 26.4, 78.4, 1453 } }, e = { 1439, "鲍雷斯·维沙克公爵", "暴风城", 0, 0, 1453 }, note = "请愿者大厅在暴风城要塞里，进门第一条右转走廊即是。" },
    [364] = { n = "The Mindless Ones", cn = "无脑的僵尸", l = 2, r = 1, f = "H", s = { { 1569, "暗影牧师萨维斯", "提瑞斯法林地", 30.8, 66.2, 1420 } }, e = { 1569, "暗影牧师萨维斯", "提瑞斯法林地", 30.8, 66.2, 1420 }, note = "目标怪就在镇外且不主动攻击，可以一只一只拉出来打，战斗间隙足够回血回蓝；注意任务目标是瘟疫食尸鬼而非瘟疫僵尸。" },
    [397] = { n = "You Have Served Us Well", cn = "干得好", l = 30, r = 25, f = "A", races = { 1, 7 }, s = { { 1435, "黑爪加尔德斯", "暴风城", 26.4, 78.4, 1453 } }, e = { 1733, "兹吉", "暴风城", 26.4, 78.4, 1453 }, items = { 3556 }, note = "术士专属任务，《名酿》链的后续，实际 25 级左右即可接取并完成。" },
    [972] = { n = "Water Sapta", cn = "水之灵契", l = 20, r = 20, f = "H", s = { { 5901, "水之先知伊斯伦", "贫瘠之地", 65.8, 43.8, 1413 } }, e = { 5901, "水之先知伊斯伦", "贫瘠之地", 65.8, 43.8, 1413 }, items = { 6637 } },
    [1103] = { n = "Call of Water", cn = "水之召唤", l = 23, r = 20, f = "H", races = { 2, 6, 8, 96 }, s = { { 7007, "提夫·摩杜恩", "银松森林", 37.4, 44, 1421 } }, e = { 7007, "提夫·摩杜恩", "银松森林", 37.4, 44, 1421 }, note = "先与身旁的巨魔对话，他会直接帮你重新召出水元素，不必再跑回棘齿城，省去大段往返路程。" },
    [1442] = { n = "Seeking the Kor Gem", cn = "寻找科尔宝石", l = 22, r = 20, f = "A", races = { 1, 3 }, s = { { 3649, "桑迪斯·织风", "黑海岸", 37.4, 40.2, 1439 } }, e = { 3649, "桑迪斯·织风", "黑海岸", 37.4, 40.2, 1439 }, items = { 7083 }, note = "先接任务再刷怪，避免白刷；腐化的科尔宝石由副本内外的暗滩纳迦掉落，几只内基本必出。" },
    [1462] = { n = "Earth Sapta", cn = "大地灵契", l = 4, r = 4, f = "H", s = { { 5888, "鸦羽先知", "莫高雷", 44.8, 76.2, 1412 } }, e = { 5888, "鸦羽先知", "莫高雷", 44.8, 76.2, 1412 }, items = { 6635 } },
    [1463] = { n = "Earth Sapta", cn = "大地灵契", l = 4, r = 4, f = "H", s = { { 5887, "坎纳甘·地鸣", "杜隆塔尔", 42.4, 69, 1411 } }, e = { 5887, "坎纳甘·地鸣", "杜隆塔尔", 42.4, 69, 1411 }, items = { 6635 } },
    [1464] = { n = "Fire Sapta", cn = "火焰灵契", l = 13, r = 10, f = "H", s = { { 5900, "泰尔夫·祖拉姆", "杜隆塔尔", 38.6, 58.8, 1411 } }, e = { 5900, "泰尔夫·祖拉姆", "杜隆塔尔", 38.6, 58.8, 1411 }, items = { 6636 } },
    [1470] = { n = "Piercing the Veil", cn = "控制小鬼", l = 3, r = 1, f = "H", races = { 2, 5 }, s = { { 5667, "温雅·玛山德", "提瑞斯法林地", 31, 66.2, 1420 } }, e = { 5667, "温雅·玛山德", "提瑞斯法林地", 31, 66.2, 1420 }, spells = { 688 }, note = "目标骷髅只有 3 级，头骨掉率一般（大约五只出三个），在镇外墓地区域刷即可。" },
    [1471] = { n = "The Binding", cn = "誓缚", l = 10, r = 10, f = "H", races = { 2, 5 }, s = { { 5675, "凯伦丁·哈加尔", "幽暗城", 85, 25.6, 1458 } }, e = { 5675, "凯伦丁·哈加尔", "幽暗城", 85, 25.6, 1458 }, spells = { 697 }, note = "站进紫光召唤法阵，用召唤符文召出虚空行者，再用暗影箭、献祭将其击杀；小心路过的巡逻卫兵抢先击杀导致任务不计完成。" },
    [1472] = { n = "Devourer of Souls", cn = "噬魂者", l = 20, r = 20, f = "H", races = { 2, 5, 8 }, s = { { 5675, "凯伦丁·哈加尔", "幽暗城", 85, 25.6, 1458 } }, e = { 5693, "高德瑞克·法杉", "幽暗城", 85, 14.8, 1458 }, note = "第二次击杀在希尔斯布莱德往阿拉希的大路上，建议选人少时段沿路小心走；部落玩家改做奥格瑞玛的魅魔任务会轻松很多。" },
    [1473] = { n = "Creature of the Void", cn = "虚空中的生物", l = 10, r = 10, f = "H", races = { 2, 5 }, s = { { 5675, "凯伦丁·哈加尔", "幽暗城", 85, 25.6, 1458 } }, e = { 5675, "凯伦丁·哈加尔", "幽暗城", 85, 25.6, 1458 }, note = "从幽暗城下水道出去可直达目标高塔，任务物品就在塔内的小箱子里，10 余级即可轻松完成。" },
    [1474] = { n = "The Binding", cn = "誓缚", l = 20, r = 20, f = "H", races = { 2, 5 }, s = { { 5675, "凯伦丁·哈加尔", "幽暗城", 85, 25.6, 1458 } }, e = { 5675, "凯伦丁·哈加尔", "幽暗城", 85, 25.6, 1458 }, items = { 22243 }, spells = { 712 } },
    [1476] = { n = "Hearts of the Pure", cn = "纯洁者之心", l = 20, r = 20, f = "H", races = { 2, 5 }, s = { { 5693, "高德瑞克·法杉", "幽暗城", 85, 14.8, 1458 } }, e = { 5675, "凯伦丁·哈加尔", "幽暗城", 85, 25.6, 1458 }, note = "科马·维拉尔在湿地北入口的桥后(湿地 50,12)，与他对话会强制开启 PVP 状态；达林在银松森林格雷迈恩之墙附近(银松森林 46,86)。" },
    [1478] = { n = "Halgar's Summons", cn = "哈加尔的召唤", l = 10, r = 10, f = "H", races = { 2, 5 }, s = { { 5724, "埃格隆·卡加尔", "提瑞斯法林地", 61.6, 52.6, 1420 } }, e = { 5675, "凯伦丁·哈加尔", "幽暗城", 85, 25.6, 1458 }, note = "起始 NPC 阿格隆·坎吉尔(提瑞斯法林地-布瑞尔 61,52)，在旅店二楼术士训练师旁；回幽暗城交给卡伦丁·哈尔加(幽暗城 84,24)。" },
    [1485] = { n = "Vile Familiars", cn = "邪灵劣魔", l = 4, r = 1, f = "H", races = { 2, 5, 8 }, s = { { 5765, "鲁赞", "杜隆塔尔", 42.6, 69, 1411 } }, e = { 5765, "鲁赞", "杜隆塔尔", 42.6, 69, 1411 }, spells = { 688 } },
    [1498] = { n = "Path of Defense", cn = "防御之道", l = 10, r = 10, f = "H", s = { { 5810, "犹塞克", "贫瘠之地", 61.4, 21, 1413 } }, e = { 5810, "犹塞克", "贫瘠之地", 61.4, 21, 1413 }, spells = { 71 }, note = "雷蜥蜴在杜隆塔尔(杜隆塔尔 39,30)；完成除防御姿态外，还会一并教会破甲与嘲讽。" },
    [1499] = { n = "Vile Familiars", cn = "邪灵劣魔", l = 4, r = 1, f = "H", races = { 2, 5, 8 }, s = { { 5765, "鲁赞", "杜隆塔尔", 42.6, 69, 1411 } }, e = { 3145, "祖雷萨", "杜隆塔尔", 42.8, 69, 1411 }, items = { 4925, 5778 } },
    [1501] = { n = "Creature of the Void", cn = "虚空中的生物", l = 11, r = 10, f = "H", races = { 2, 5, 8 }, s = { { 5875, "莫达克·黑拳", "奥格瑞玛", 48.2, 45.6, 1454 } }, e = { 5875, "莫达克·黑拳", "奥格瑞玛", 48.2, 45.6, 1454 }, note = "洞内沿右侧向上的路走到底，石板就在顶端的箱子里；洞内怪密集且刷新快，多带食物饮水，低级时打起来比较吃力。" },
    [1502] = { n = "Thun'grim Firegaze", cn = "索恩格瑞姆·火眼", l = 10, r = 10, f = "H", s = { { 5810, "犹塞克", "贫瘠之地", 61.4, 21, 1413 } }, e = { 5878, "索恩格瑞姆·火眼", "贫瘠之地", 57.2, 30.2, 1413 }, note = "索恩格瑞姆在山顶(贫瘠之地 57,30)，身旁有熔炉与铁砧；山坡四面都能爬，从(贫瘠之地 54,29)上山最近，沿途基本不用打架。" },
    [1503] = { n = "Forged Steel", cn = "锻造好的钢锭", l = 10, r = 10, f = "H", s = { { 5878, "索恩格瑞姆·火眼", "贫瘠之地", 57.2, 30.2, 1413 } }, e = { 5878, "索恩格瑞姆·火眼", "贫瘠之地", 57.2, 30.2, 1413 }, items = { 7326, 7328, 7327, 7329 }, note = "锻造好的钢锭在索恩格瑞姆西北山下的野猪人营地(贫瘠之地 55,26)，就在断掉的货车下(贫瘠之地 56,27)；顺路可清「扰乱攻击」。" },
    [1504] = { n = "The Binding", cn = "誓缚", l = 11, r = 10, f = "H", races = { 2, 5, 8 }, s = { { 5875, "莫达克·黑拳", "奥格瑞玛", 48.2, 45.6, 1454 } }, e = { 5875, "莫达克·黑拳", "奥格瑞玛", 48.2, 45.6, 1454 }, spells = { 697 }, note = "召唤点在尼尔鲁·火刃的小屋里(奥格瑞玛-怒焰裂谷门口旁)，进屋使用召唤道具召出虚空行者并将其击败，回甘鲁尔处交差即可。" },
    [1505] = { n = "Veteran Uzzek", cn = "老兵犹塞克", l = 10, r = 10, f = "H", s = { { 3041, "托姆·暴怒图腾", "雷霆崖", 57.6, 87.2, 1456 }, { 3063, "克朗·石蹄", "莫高雷", 49.4, 60.4, 1412 }, { 3169, "塔绍尔·锯痕", "杜隆塔尔", 54.2, 42.4, 1411 }, { 3354, "索瑞克", "奥格瑞玛", 80.2, 32.4, 1454 } }, e = { 5810, "犹塞克", "贫瘠之地", 61.4, 21, 1413 }, note = "犹塞克在过桥后的贫瘠之地一侧(贫瘠之地 61,21)，站在远望岗哨后方的大树旁；牛头人战士版本由雷霆崖猎人高地处起始。" },
    [1506] = { n = "Gan'rul's Summons", cn = "甘鲁尔的召唤", l = 10, r = 10, f = "H", races = { 2, 5, 8 }, s = { { 3294, "奥菲克", "杜隆塔尔", 54.2, 41.2, 1411 } }, e = { 5875, "莫达克·黑拳", "奥格瑞玛", 48.2, 45.6, 1454 }, note = "目标 NPC 在奥格瑞玛术士训练师旁；即便已在他处完成过同名恶魔任务，这里仍可再接（不会再给第二只，但有经验与金币）。" },
    [1507] = { n = "Devourer of Souls", cn = "噬魂者", l = 20, r = 20, f = "H", races = { 2, 5, 8 }, s = { { 5875, "莫达克·黑拳", "奥格瑞玛", 48.2, 45.6, 1454 } }, e = { 5909, "卡祖尔", "奥格瑞玛", 47.2, 46.6, 1454 } },
    [1508] = { n = "Blind Cazul", cn = "盲眼卡祖尔", l = 20, r = 20, f = "H", races = { 2, 5, 8 }, s = { { 5909, "卡祖尔", "奥格瑞玛", 47.2, 46.6, 1454 } }, e = { 5910, "赞卡沙", "奥格瑞玛", 37, 59.6, 1454 }, note = "位置在飞行点木桥下来右手边(贫瘠之地-棘齿城 37,60)；即使已经学会召唤魅魔，这个任务仍然可以接。" },
    [1509] = { n = "News of Dogran", cn = "多格兰的消息", l = 20, r = 20, f = "H", races = { 2, 5, 8 }, s = { { 5910, "赞卡沙", "奥格瑞玛", 37, 59.6, 1454 } }, e = { 3464, "加兹罗格", "贫瘠之地", 51.8, 30.2, 1413 }, note = "任务目标 NPC 就在十字路口(贫瘠之地-十字路口 51,30)，紧邻飞行点，一眼就能看到。" },
    [1510] = { n = "News of Dogran", cn = "多格兰的消息", l = 20, r = 20, f = "H", races = { 2, 5, 8 }, s = { { 3464, "加兹罗格", "贫瘠之地", 51.8, 30.2, 1413 } }, e = { 4197, "肯兹格拉", "石爪山脉", 73.2, 95, 1442 }, note = "肯兹格拉在石爪山脉的马拉卡金营地(石爪山脉 73,95)；进入石爪后沿悬崖一侧的小路往南走可以无战斗到达，见到左侧建筑后左转。" },
    [1511] = { n = "Ken'zigla's Draught", cn = "肯兹格拉的伤药", l = 20, r = 20, f = "H", races = { 2, 5 }, s = { { 4197, "肯兹格拉", "石爪山脉", 73.2, 95, 1442 } }, e = { 5911, "步兵劳格玛", "贫瘠之地", 44.6, 59.2, 1413 }, note = "交付点在陶拉祖营地(贫瘠之地 46,60)，坐标在贫瘠之地，别与石爪山脉那头的同名NPC混淆。" },
    [1512] = { n = "Love's Gift", cn = "爱的礼物", l = 20, r = 20, f = "H", races = { 2, 5 }, s = { { 5908, "步兵多格兰", "贫瘠之地", 43.2, 47.8, 1413 } }, e = { 5875, "莫达克·黑拳", "奥格瑞玛", 48.2, 45.6, 1454 }, note = "目标 NPC 在奥格瑞玛暗影裂口的小屋里(奥格瑞玛 48,45)，也就是引导你获取新仆从的那位。" },
    [1513] = { n = "The Binding", cn = "誓缚", l = 20, r = 20, f = "H", races = { 2, 5 }, s = { { 5875, "莫达克·黑拳", "奥格瑞玛", 48.2, 45.6, 1454 } }, e = { 5875, "莫达克·黑拳", "奥格瑞玛", 48.2, 45.6, 1454 }, items = { 22243 }, spells = { 712 }, note = "召唤点在尼尔鲁·火刃的帐篷里(奥格瑞玛-怒焰裂谷入口旁)，击杀魅魔非常轻松。" },
    [1515] = { n = "Dogran's Captivity", cn = "多格兰之囚", l = 20, r = 20, f = "H", races = { 2, 5 }, s = { { 5911, "步兵劳格玛", "贫瘠之地", 44.6, 59.2, 1413 } }, e = { 5908, "步兵多格兰", "贫瘠之地", 43.2, 47.8, 1413 }, note = "多格兰(贫瘠之地 43,47)，附近可能有 22 级精英看守；最省事的打法是让虚空行者先冲过去拉怪，再趁机救人。" },
    [1516] = { n = "Call of Earth", cn = "大地的召唤", l = 4, r = 4, f = "H", races = { 2, 6, 8 }, s = { { 5887, "坎纳甘·地鸣", "杜隆塔尔", 42.4, 69, 1411 } }, e = { 5887, "坎纳甘·地鸣", "杜隆塔尔", 42.4, 69, 1411 }, note = "邪犬就在灼刃氏族秘会(杜隆塔尔 45,56)，与「邪恶的爪牙」任务同点，可以一并清掉。" },
    [1517] = { n = "Call of Earth", cn = "大地的召唤", l = 4, r = 4, f = "H", races = { 2, 6, 8 }, s = { { 5887, "坎纳甘·地鸣", "杜隆塔尔", 42.4, 69, 1411 } }, e = { 5891, "大地之魂", "杜隆塔尔", 44, 76, 1411 }, note = "隐藏小路入口在试炼谷南侧(杜隆塔尔 41,73)，沿路上去即到灵魂之岩(杜隆塔尔 44,76)。" },
    [1518] = { n = "Call of Earth", cn = "大地的召唤", l = 4, r = 4, f = "H", races = { 2, 6, 8 }, s = { { 5891, "大地之魂", "丹莫罗", 24.8, 61.8, 1426 }, { 5891, "大地之魂", "杜隆塔尔", 44, 76, 1411 }, { 5891, "大地之魂", "莫高雷", 53.8, 80.4, 1412 } }, e = { 5887, "坎纳甘·地鸣", "杜隆塔尔", 42.4, 69, 1411 }, items = { 5175 }, spells = { 8071 }, note = "回村交给问号 NPC 即可获得第一件大地图腾与石肤图腾技能；图腾需要放在包里，施放对应系图腾时会用到。" },
    [1519] = { n = "Call of Earth", cn = "大地的召唤", l = 4, r = 4, f = "H", races = { 2, 6 }, s = { { 5888, "鸦羽先知", "莫高雷", 44.8, 76.2, 1412 } }, e = { 5888, "鸦羽先知", "莫高雷", 44.8, 76.2, 1412 }, note = "到纳拉其营地北边的沟谷杀荆棘背野人萨满，收集 2 份药膏；掉率非 100%，可能要多杀几只。" },
    [1520] = { n = "Call of Earth", cn = "大地的召唤", l = 4, r = 4, f = "H", races = { 2, 6, 8 }, s = { { 5888, "鸦羽先知", "莫高雷", 44.8, 76.2, 1412 } }, e = { 5891, "大地之魂", "莫高雷", 53.8, 80.4, 1412 }, note = "科多岩在鹰风祖母所在水井的正东(莫高雷 53,80)；与大地之次级显灵对话后只有 20 分钟时效，别让它消失，否则要重做。" },
    [1521] = { n = "Call of Earth", cn = "大地的召唤", l = 4, r = 4, f = "H", races = { 2, 6, 8 }, s = { { 5891, "大地之魂", "丹莫罗", 24.8, 61.8, 1426 }, { 5891, "大地之魂", "杜隆塔尔", 44, 76, 1411 }, { 5891, "大地之魂", "莫高雷", 53.8, 80.4, 1412 } }, e = { 5888, "鸦羽先知", "莫高雷", 44.8, 76.2, 1412 }, items = { 5175 }, spells = { 8071 } },
    [1522] = { n = "Call of Fire", cn = "火焰的召唤", l = 10, r = 10, f = "H", races = { 2, 6, 8 }, s = { { 5892, "希尔恩·火结", "奥格瑞玛", 37.8, 37.4, 1454 } }, e = { 5907, "卡纳尔·菲斯", "贫瘠之地", 55.8, 20, 1413 }, note = "克兰纳尔·菲斯在十字路口东北的农场(贫瘠之地 56,20)，出城向北走到岔路走右边。" },
    [1523] = { n = "Call of Fire", cn = "火焰的召唤", l = 10, r = 10, f = "H", races = { 2, 6, 8 }, s = { { 5906, "萨尼斯·织火", "雷霆崖", 25.2, 21, 1456 } }, e = { 5907, "卡纳尔·菲斯", "贫瘠之地", 55.8, 20, 1413 } },
    [1524] = { n = "Call of Fire", cn = "火焰的召唤", l = 11, r = 10, f = "H", races = { 2, 6, 8 }, s = { { 5907, "卡纳尔·菲斯", "贫瘠之地", 55.8, 20, 1413 } }, e = { 5900, "泰尔夫·祖拉姆", "杜隆塔尔", 38.6, 58.8, 1411 }, note = "特尔·尤拉姆其实在杜隆塔尔(杜隆塔尔 39,59)：沿贫瘠之路走，过大河前左转不过桥，山脚处一块黑色岩石就是上崖入口的标记。" },
    [1525] = { n = "Call of Fire", cn = "火焰的召唤", l = 12, r = 10, f = "H", races = { 2, 6, 8 }, s = { { 5900, "泰尔夫·祖拉姆", "杜隆塔尔", 38.6, 58.8, 1411 } }, e = { 5900, "泰尔夫·祖拉姆", "杜隆塔尔", 38.6, 58.8, 1411 }, items = { 6636 }, note = "施法材料包由剃刀岭北边灼刃教徒掉落(杜隆塔尔 51,26，洞口在 52,29，别下沟谷)；火焰焦油由十字路口东侧荆棘岗的剃刀荆棘施法系怪掉落(贫瘠之地 55,26)，守卫与猎手不出。" },
    [1526] = { n = "Call of Fire", cn = "火焰的召唤", l = 13, r = 10, f = "H", races = { 2, 6, 8 }, s = { { 5900, "泰尔夫·祖拉姆", "杜隆塔尔", 38.6, 58.8, 1411 } }, e = { 61934, "蜥蜴人治疗师", "杜隆塔尔", 38.9, 58.2, 1411 }, items = { 6654 }, note = "在特尔身旁的大岩石附近使用任务药剂召出火焰之次级显灵；战斗用石化武器配合大地震击（火系法术对他效果差），击败后拾取发光的余烬放进火盆即完成。" },
    [1527] = { n = "Call of Fire", cn = "火焰的召唤", l = 13, r = 10, f = "H", races = { 2, 6, 8 }, s = { { 61934, "蜥蜴人治疗师", "杜隆塔尔", 38.9, 58.2, 1411 }, { 61934, "蜥蜴人治疗师", "洛克莫丹", 31.9, 64.5, 1432 } }, e = { 5907, "卡纳尔·菲斯", "贫瘠之地", 55.8, 20, 1413 }, items = { 5176, 263412 }, spells = { 3599 }, note = "克兰纳尔·菲斯(贫瘠之地 55,20)，在路边被蜜蜂追的孩童再往东一点；注意坐标在贫瘠之地，别跑去杜隆塔尔找。" },
    [1528] = { n = "Call of Water", cn = "水之召唤", l = 20, r = 20, f = "H", races = { 2, 6, 8 }, s = { { 5892, "希尔恩·火结", "奥格瑞玛", 37.8, 37.4, 1454 } }, e = { 5901, "水之先知伊斯伦", "贫瘠之地", 65.8, 43.8, 1413 }, note = "艾斯兰·水汐在渔夫小屋(贫瘠之地 65,43)，飞到棘齿城再走过去；水之召唤是萨满经典长链，跑路段多，建议提前规划路线。" },
    [1529] = { n = "Call of Water", cn = "水之召唤", l = 20, r = 20, f = "H", races = { 2, 6, 8 }, s = { { 5906, "萨尼斯·织火", "雷霆崖", 25.2, 21, 1456 } }, e = { 5901, "水之先知伊斯伦", "贫瘠之地", 65.8, 43.8, 1413 } },
    [1530] = { n = "Call of Water", cn = "水之召唤", l = 22, r = 20, f = "H", races = { 2, 6, 8, 96 }, s = { { 5901, "水之先知伊斯伦", "贫瘠之地", 65.8, 43.8, 1413 } }, e = { 5899, "布瑞恩", "贫瘠之地", 43.4, 77.4, 1413 }, note = "盐水怪在黑荆岭(贫瘠之地 43,77)，陶拉祖营地以南；顺路留意 25 级雷鹰瓦什特·帕温，掉落的任务物品可交回营地拿额外经验。" },
    [1531] = { n = "Call of Air", cn = "空气的召唤", l = 30, r = 30, f = "H", races = { 2, 6, 8 }, s = { { 5892, "希尔恩·火结", "奥格瑞玛", 37.8, 37.4, 1454 } }, e = { 5905, "普拉特·白云", "千针石林", 53.6, 42.8, 1441 }, items = { 5178 }, note = "云游者普拉特在崖上洞口(千针石林 54,43)，沿小路爬上高台即可对话；完成可获 1 小时强增益：跑速 +40%、攻击速度 +30%。" },
    [1532] = { n = "Call of Air", cn = "空气的召唤", l = 30, r = 30, f = "H", races = { 2, 6, 8 }, s = { { 5906, "萨尼斯·织火", "雷霆崖", 25.2, 21, 1456 } }, e = { 5905, "普拉特·白云", "千针石林", 53.6, 42.8, 1441 }, items = { 5178 } },
    [1534] = { n = "Call of Water", cn = "水之召唤", l = 23, r = 20, f = "H", races = { 2, 6, 8, 96 }, s = { { 5899, "布瑞恩", "贫瘠之地", 43.4, 77.4, 1413 } }, e = { 5899, "布瑞恩", "贫瘠之地", 43.4, 77.4, 1413 }, note = "喷泉在湖心小岛上(灰谷 33,67)，四周怪 23-34 级且会缠绕，逃跑困难；湖边游荡的守护者是 ?? 精英，绕开走别去惹。" },
    [1535] = { n = "Call of Water", cn = "水之召唤", l = 22, r = 20, f = "H", races = { 2, 6, 8, 96 }, s = { { 5899, "布瑞恩", "贫瘠之地", 43.4, 77.4, 1413 } }, e = { 5899, "布瑞恩", "贫瘠之地", 43.4, 77.4, 1413 }, note = "取水点就在小屋东侧下方；打水时会弹出一只野猪人，很好打，不想打直接跑上山坡交差也行。" },
    [1536] = { n = "Call of Water", cn = "水之召唤", l = 22, r = 20, f = "H", races = { 2, 6, 8, 96 }, s = { { 5899, "布瑞恩", "贫瘠之地", 43.4, 77.4, 1413 } }, e = { 5899, "布瑞恩", "贫瘠之地", 43.4, 77.4, 1413 }, note = "水井在塔伦米尔镇中心教堂外(希尔斯布莱德丘陵-塔伦米尔)；出发前可顺路从墓穴旅馆接「前往希尔斯布莱德丘陵」，白拿一段经验。" },
    [1598] = { n = "The Stolen Tome", cn = "失窃的典籍", l = 4, r = 1, f = "A", races = { 1, 7 }, s = { { 459, "杜希拉·拉萨雷", "艾尔文森林", 49.8, 42.6, 1429 } }, e = { 459, "杜希拉·拉萨雷", "艾尔文森林", 49.8, 42.6, 1429 }, spells = { 688 }, note = "典籍在葡萄园北侧的帐篷处(艾尔文森林 56,43)，三个迪菲亚连动不能单拉；可以钻进帐篷让怪物卡住，隔着帐篷把书拿走。" },
    [1599] = { n = "Beginnings", cn = "开端", l = 4, r = 1, f = "A", races = { 1, 7 }, s = { { 460, "阿拉玛尔·格里姆", "丹莫罗", 28.6, 66.2, 1426 } }, e = { 460, "阿拉玛尔·格里姆", "丹莫罗", 28.6, 66.2, 1426 }, spells = { 688 }, note = "羽毛由山洞最深处的霜鬃新兵掉落，洞里同时只有两三只，刷新约两分钟；从入口左侧进洞可避开多余引怪。" },
    [1638] = { n = "A Warrior's Training", cn = "战士的训练", l = 10, r = 10, f = "A", s = { { 913, "里瑞亚·杜拉克", "艾尔文森林", 41, 65.8, 1429 }, { 5480, "伊尔萨·考宾", "暴风城", 78.6, 45.6, 1453 } }, e = { 6089, "哈里·伯加德", "暴风城", 74, 37.2, 1453 }, note = "「猪与哨声」酒馆在暴风城旧城区(暴风城 71,39)，邮箱旁；找哈利·伯尔加德拿酒杯，开启联盟战士防御姿态链。" },
    [1639] = { n = "Bartleby the Drunk", cn = "醉鬼巴特莱比", l = 10, r = 10, f = "A", s = { { 6089, "哈里·伯加德", "暴风城", 74, 37.2, 1453 } }, e = { 6090, "巴特莱比", "暴风城", 73.8, 36.6, 1453 }, note = "完成此任务会强制开启 PVP 状态，介意者可改走侏儒/矮人线；流程很简单：教训巴特莱比一顿拿回酒杯即可。" },
    [1640] = { n = "Beat Bartleby", cn = "击败巴特莱比", l = 10, r = 10, f = "A", s = { { 6090, "巴特莱比", "暴风城", 73.8, 36.6, 1453 } }, e = { 6090, "巴特莱比", "暴风城", 73.8, 36.6, 1453 } },
    [1641] = { n = "The Tome of Divinity", cn = "圣洁之书", l = 12, r = 12, f = "A", races = { 1 }, s = { { 6171, "达索瑞恩·拉尔", "暴风城", 40, 29.8, 1453 } }, e = { 6171, "达索瑞恩·拉尔", "暴风城", 40, 29.8, 1453 }, items = { 6775 } },
    [1642] = { n = "The Tome of Divinity", cn = "圣洁之书", l = 12, r = 12, f = "A", races = { 1 }, e = { 6171, "达索瑞恩·拉尔", "暴风城", 40, 29.8, 1453 }, note = "各族起始 NPC 不同：人类版由闪金镇铁匠铺后的威尔汉姆修士发起，把书送去暴风城大教堂；12 级可接，这条链最终学会复活术。" },
    [1643] = { n = "The Tome of Divinity", cn = "圣洁之书", l = 12, r = 12, f = "A", races = { 1 }, s = { { 6171, "达索瑞恩·拉尔", "暴风城", 40, 29.8, 1453 } }, e = { 6174, "斯蒂芬妮·特纳", "暴风城", 57, 61.8, 1453 }, note = "交付 NPC 在暴风城贸易区奶酪店旁的杂货摊(暴风城 64,72)。" },
    [1644] = { n = "The Tome of Divinity", cn = "圣洁之书", l = 13, r = 12, f = "A", races = { 1 }, s = { { 6174, "斯蒂芬妮·特纳", "暴风城", 57, 61.8, 1453 } }, e = { 6174, "斯蒂芬妮·特纳", "暴风城", 57, 61.8, 1453 }, note = "需要 10 张亚麻布，提前备好再交任务，别白跑一趟。" },
