    [1646] = { n = "The Tome of Divinity", cn = "圣洁之书", l = 12, r = 12, f = "A", races = { 3 }, e = { 6179, "蒂萨·热炉", "铁炉堡", 27.4, 12, 1455 } },
    [1647] = { n = "The Tome of Divinity", cn = "圣洁之书", l = 12, r = 12, f = "A", races = { 3 }, s = { { 6179, "蒂萨·热炉", "铁炉堡", 27.4, 12, 1455 } }, e = { 6175, "约翰·特纳", "铁炉堡", 27.8, 70, 1455 }, note = "约翰·特纳常在拍卖行门口：出秘法区右转，沿最外圈往南走就能碰到。" },
    [1648] = { n = "The Tome of Divinity", cn = "圣洁之书", l = 13, r = 12, f = "A", races = { 3 }, s = { { 6175, "约翰·特纳", "铁炉堡", 27.8, 70, 1455 } }, e = { 6175, "约翰·特纳", "铁炉堡", 27.8, 70, 1455 } },
    [1649] = { n = "The Tome of Valor", cn = "勇气之书", l = 20, r = 20, f = "A", e = { 6171, "达索瑞恩·拉尔", "暴风城", 40, 29.8, 1453 }, note = "这条链从暴风城大教堂领取《勇气之书》开始，读完书再去西部荒野找达芙妮·斯蒂尔威尔，是圣骑士的重要一环。" },
    [1650] = { n = "The Tome of Valor", cn = "勇气之书", l = 23, r = 20, f = "A", races = { 1, 3 }, s = { { 6171, "达索瑞恩·拉尔", "暴风城", 40, 29.8, 1453 } }, e = { 6182, "达芙妮·斯迪威尔", "西部荒野", 42.2, 88.6, 1436 }, note = "从死亡矿井出口出发，沿矿洞旁的小路绕到山后即达芙妮的农场(西部荒野 41,89)。" },
    [1651] = { n = "The Tome of Valor", cn = "勇气之书", l = 25, r = 20, f = "A", races = { 1, 3 }, s = { { 6182, "达芙妮·斯迪威尔", "西部荒野", 42.2, 88.6, 1436 } }, e = { 6182, "达芙妮·斯迪威尔", "西部荒野", 42.2, 88.6, 1436 }, note = "达芙妮会先走回屋子再开刷，共三波 16-18 级迪菲亚来袭；开惩戒光环打更稳。先回大教堂找杜索瑞安·拉尔接书再去找她，别被蓝问号骗过。" },
    [1652] = { n = "The Tome of Valor", cn = "勇气之书", l = 25, r = 20, f = "A", races = { 1, 3 }, s = { { 6182, "达芙妮·斯迪威尔", "西部荒野", 42.2, 88.6, 1436 } }, e = { 6171, "达索瑞恩·拉尔", "暴风城", 40, 29.8, 1453 }, items = { 9607 }, spells = { 5502 } },
    [1653] = { n = "The Test of Righteousness", cn = "正义试炼", l = 21, r = 20, f = "A", races = { 1, 3 }, s = { { 6171, "达索瑞恩·拉尔", "暴风城", 40, 29.8, 1453 } }, e = { 6181, "乔丹·斯迪威尔", "丹莫罗", 52.4, 36.8, 1426 }, note = "目标 NPC 就在铁炉堡大门外(丹莫罗 52,36)。" },
    [1654] = { n = "The Test of Righteousness", cn = "正义试炼", l = 22, r = 20, f = "A", races = { 1, 3 }, s = { { 6181, "乔丹·斯迪威尔", "丹莫罗", 52.4, 36.8, 1426 } }, e = { 6181, "乔丹·斯迪威尔", "丹莫罗", 52.4, 36.8, 1426 }, note = "要集齐四件物品，其中两件需另接任务：白岩橡木由死亡矿井造桅室的地精木匠掉落；锻造锤在影牙城堡，22 级可单刷但组队更稳；纳迦要打黑深渊的潮汐纳迦，不是怨尾纳迦。" },
    [1655] = { n = "Bailor's Ore Shipment", cn = "白洛尔的矿石", l = 22, r = 20, f = "A", races = { 1, 3 }, s = { { 6241, "白洛尔·石手", "洛克莫丹", 36, 45, 1432 } }, e = { 6241, "白洛尔·石手", "洛克莫丹", 36, 45, 1432 }, items = { 6993 } },
    [1661] = { n = "The Tome of Nobility", cn = "高贵之书", l = 40, r = 40, f = "A", races = { 1, 3 }, s = { { 6171, "达索瑞恩·拉尔", "暴风城", 40, 29.8, 1453 } }, e = { 6171, "达索瑞恩·拉尔", "暴风城", 40, 29.8, 1453 }, spells = { 13819 } },
    [1665] = { n = "Bartleby's Mug", cn = "巴特莱比的酒杯", l = 10, r = 10, f = "A", s = { { 6090, "巴特莱比", "暴风城", 73.8, 36.6, 1453 } }, e = { 6089, "哈里·伯加德", "暴风城", 74, 37.2, 1453 }, spells = { 71 }, note = "完成后即学会防御姿态、嘲讽与破甲，是战士的核心起步技能；后续去找治安官哈迦德。" },
    [1666] = { n = "Marshal Haggard", cn = "治安官哈迦德", l = 10, r = 10, f = "A", s = { { 6089, "哈里·伯加德", "暴风城", 74, 37.2, 1453 } }, e = { 294, "治安官哈迦德", "艾尔文森林", 84.6, 69.4, 1429 }, note = "哈迦德在东谷伐木场东南角(艾尔文森林 84,69)；接了后续尽快完成，有反馈称下线后该任务可能从任务日志中消失。" },
    [1667] = { n = "Dead-tooth Jack", cn = "蛀牙杰克", l = 10, r = 10, f = "A", s = { { 294, "治安官哈迦德", "艾尔文森林", 84.6, 69.4, 1429 } }, e = { 294, "治安官哈迦德", "艾尔文森林", 84.6, 69.4, 1429 }, items = { 6979, 6983, 6980, 6985 }, note = "蛀牙杰克(艾尔文森林 89,78)带着两个随从，建议带远程武器把他们逐个拉回来打；此地还会刷稀有怪，开打前看清楚目标。" },
    [1678] = { n = "Vejrek", cn = "维吉雷克", l = 11, r = 10, f = "A", s = { { 6114, "穆伦·雷矛", "铁炉堡", 70.6, 90.4, 1455 } }, e = { 6114, "穆伦·雷矛", "铁炉堡", 70.6, 90.4, 1455 }, spells = { 71 }, note = "维吉雷克的小屋在霜鬃要塞以南：一路向南走到山根再折向东，找到一处向南延伸的短坡即是；完成后同样学会防御姿态、嘲讽与破甲。" },
    [1679] = { n = "Muren Stormpike", cn = "穆伦·雷矛", l = 10, r = 10, f = "A", races = { 1, 3, 7 }, s = { { 1229, "格兰尼斯·快斧", "丹莫罗", 47.2, 52.6, 1426 } }, e = { 6114, "穆伦·雷矛", "铁炉堡", 70.6, 90.4, 1455 } },
    [1680] = { n = "Tormus Deepforge", cn = "托姆斯·深炉", l = 11, r = 10, f = "A", s = { { 6114, "穆伦·雷矛", "铁炉堡", 70.6, 90.4, 1455 } }, e = { 6031, "托姆斯·深炉", "铁炉堡", 48.6, 43, 1455 }, note = "托姆斯·深炉在铁炉堡大熔炉正中央，就在钢铸者格鲁姆努斯身旁。" },
    [1681] = { n = "Ironband's Compound", cn = "铁环营地", l = 11, r = 10, f = "A", s = { { 6031, "托姆斯·深炉", "铁炉堡", 48.6, 43, 1455 } }, e = { 6031, "托姆斯·深炉", "铁炉堡", 48.6, 43, 1455 }, note = "铁环营地在头盔床湖南侧(丹莫罗 78,62)，幽影矿石就放在营地南侧那栋建筑里。" },
    [1682] = { n = "Grey Iron Weapons", cn = "灰铁武器", l = 10, r = 10, f = "A", s = { { 6031, "托姆斯·深炉", "铁炉堡", 48.6, 43, 1455 } }, e = { 6031, "托姆斯·深炉", "铁炉堡", 48.6, 43, 1455 }, items = { 6978, 6982, 6981, 6984 } },
    [1683] = { n = "Vorlus Vilehoof", cn = "沃鲁斯·邪蹄", l = 10, r = 10, f = "A", s = { { 4088, "艾兰娜瑞", "达纳苏斯", 57.4, 34.8, 1457 } }, e = { 4088, "艾兰娜瑞", "达纳苏斯", 57.4, 34.8, 1457 }, spells = { 71 }, note = "小路入口在多兰纳尔以西(泰达希尔 49,59)，一路有灯笼照明很好认；10 级恶魔很好打，拾取号角回去学防御姿态。" },
    [1684] = { n = "Elanaria", cn = "艾兰娜瑞", l = 10, r = 10, f = "A", s = { { 2151, "哨兵阿玛拉·夜行者", "泰达希尔", 55.6, 58.4, 1438 }, { 3598, "凯拉·风刃", "泰达希尔", 56.2, 59.2, 1438 } }, e = { 4088, "艾兰娜瑞", "达纳苏斯", 57.4, 34.8, 1457 } },
    [1685] = { n = "Gakin's Summons", cn = "加科因的召唤", l = 10, r = 10, f = "A", races = { 1, 7 }, s = { { 6121, "雷门·玛考特", "艾尔文森林", 44.4, 66.2, 1429 } }, e = { 6122, "黑暗缚灵者加科因", "暴风城", 25.4, 78.4, 1453 }, note = "加科因在暴风城法师区的「宰羊」旅店(暴风城 25,78)，召唤法阵在旅店地下室。" },
    [1686] = { n = "The Shade of Elura", cn = "艾鲁拉的阴影", l = 10, r = 10, f = "A", s = { { 4088, "艾兰娜瑞", "达纳苏斯", 57.4, 34.8, 1457 } }, e = { 4088, "艾兰娜瑞", "达纳苏斯", 57.4, 34.8, 1457 }, note = "板条箱散落在黑海岸沉船四周(黑海岸 31,45)，码头旁大海龟尸体附近的水下；备一瓶水下呼吸药剂会轻松很多。" },
    [1688] = { n = "Surena Caledon", cn = "苏伦娜·凯尔东", l = 10, r = 10, f = "A", races = { 1, 7 }, s = { { 6122, "黑暗缚灵者加科因", "暴风城", 25.4, 78.4, 1453 } }, e = { 6122, "黑暗缚灵者加科因", "暴风城", 25.4, 78.4, 1453 }, note = "苏伦娜在闪金镇东侧南瓜田的屋子里(艾尔文森林 71,80)；「收藏家」的目标也在同一间屋，可顺路一起清。" },
    [1689] = { n = "The Binding", cn = "誓缚", l = 10, r = 10, f = "A", races = { 1, 7 }, s = { { 6122, "黑暗缚灵者加科因", "暴风城", 25.4, 78.4, 1453 } }, e = { 6122, "黑暗缚灵者加科因", "暴风城", 25.4, 78.4, 1453 }, spells = { 697 }, note = "召唤法阵不好找：从加肯房间对面的下坡道下去，连走两段全靠右的楼梯，再右转下最后一段即到；召唤需要一颗灵魂碎片，提前备好。" },
    [1692] = { n = "Smith Mathiel", cn = "铁匠玛希尔", l = 10, r = 10, f = "A", s = { { 4088, "艾兰娜瑞", "达纳苏斯", 57.4, 34.8, 1457 } }, e = { 6142, "玛希尔", "达纳苏斯", 59.2, 45.4, 1457 } },
    [1693] = { n = "Weapons of Elunite", cn = "月神武器", l = 10, r = 10, f = "A", s = { { 6142, "玛希尔", "达纳苏斯", 59.2, 45.4, 1457 } }, e = { 6142, "玛希尔", "达纳苏斯", 59.2, 45.4, 1457 }, items = { 6966, 6968, 6969, 6967 } },
    [1698] = { n = "Yorus Barleybrew", cn = "犹鲁斯·麦酒", l = 20, r = 20, f = "A", s = { { 5113, "凯夫·重锤", "铁炉堡", 70, 90.6, 1455 }, { 5479, "武神", "暴风城", 78.8, 45.6, 1453 }, { 7315, "达纳斯·刃歌", "达纳苏斯", 58.6, 35.4, 1457 } }, e = { 6166, "犹鲁斯·麦酒", "赤脊山", 26.6, 44.8, 1433 } },
    [1699] = { n = "The Rethban Gauntlet", cn = "往返瑞斯班洞穴", l = 22, r = 20, f = "A", s = { { 6166, "犹鲁斯·麦酒", "赤脊山", 26.6, 44.8, 1433 } }, e = { 6166, "犹鲁斯·麦酒", "赤脊山", 26.6, 44.8, 1433 }, note = "洞穴在(赤脊山 20,27)，20 级可单刷；建议接任务前先踩点清掉沿途几只怪——半路死亡释放即告失败。" },
    [1700] = { n = "Grimand Elmore", cn = "格瑞曼德·艾尔默", l = 28, r = 20, f = "A", races = { 1 }, s = { { 5413, "弗伦·长须", "暴风城", 58, 16.8, 1453 } }, e = { 1416, "格瑞曼德·艾尔默", "暴风城", 51.6, 12.2, 1453 }, note = "矮人版火硬锁甲链的一环，接它之前须先完成《犹鲁斯·麦酒》起头的链；其他种族各有对应后续版本。" },
    [1701] = { n = "Fire Hardened Mail", cn = "弗伦的铠甲", l = 28, r = 20, f = "A", s = { { 5413, "弗伦·长须", "暴风城", 58, 16.8, 1453 } }, e = { 5413, "弗伦·长须", "暴风城", 58, 16.8, 1453 }, note = "烧焦的蛛牙 x50 由(湿地 54,64)的水蛭与洞窟潜伏者掉落；焦黑号角 x12 出自(石爪山脉 33,72)的幼奇美拉，电镀号角则由奇美拉母兽掉落，同点可一起刷；完成胸甲后，头/手/腿三件后续按种族交不同 NPC。" },
    [1702] = { n = "The Shieldsmith", cn = "铸盾师", l = 22, r = 20, f = "A", s = { { 6166, "犹鲁斯·麦酒", "赤脊山", 26.6, 44.8, 1433 } }, e = { 5413, "弗伦·长须", "暴风城", 58, 16.8, 1453 }, items = { 6970 }, note = "弗伦·朗比尔德在暴风城矮人区(暴风城 58,16)。" },
    [1703] = { n = "Mathiel", cn = "玛希尔", l = 28, r = 20, f = "A", races = { 4 }, s = { { 5413, "弗伦·长须", "暴风城", 58, 16.8, 1453 } }, e = { 6142, "玛希尔", "达纳苏斯", 59.2, 45.4, 1457 }, note = "玛希尔在达纳苏斯战士平台(达纳苏斯 59,45)，20 级即可接，没有弗伦的介绍信也能直接接。" },
    [1704] = { n = "Klockmort Spannerspan", cn = "科罗莫特·钢尺", l = 28, r = 20, f = "A", races = { 3, 7 }, s = { { 5413, "弗伦·长须", "暴风城", 58, 16.8, 1453 } }, e = { 6169, "科罗莫特·钢尺", "铁炉堡", 68.2, 46.2, 1455 }, note = "克洛克莫特在铁炉堡工匠区(铁炉堡 68,46)，工程师训练师附近。" },
    [1705] = { n = "Burning Blood", cn = "燃烧之血", l = 28, r = 20, f = "A", s = { { 1416, "格瑞曼德·艾尔默", "暴风城", 51.6, 12.2, 1453 } }, e = { 1416, "格瑞曼德·艾尔默", "暴风城", 51.6, 12.2, 1453 }, note = "脏水怪在洞口刷新(赤脊山 72,74)，与「森林狼人」链第三步的怪同区，可顺路一起清。" },
    [1706] = { n = "Grimand's Armor", cn = "格瑞曼德的铠甲", l = 30, r = 20, f = "A", s = { { 1416, "格瑞曼德·艾尔默", "暴风城", 51.6, 12.2, 1453 } }, e = { 1416, "格瑞曼德·艾尔默", "暴风城", 51.6, 12.2, 1453 }, items = { 6971 }, note = "属于从《犹鲁斯·麦酒》起头的火硬多段链；其余火硬件（头/手/腿）要在完成胸甲任务后才会逐一开放。" },
    [1708] = { n = "Iron Coral", cn = "铁珊瑚", l = 29, r = 20, f = "A", s = { { 6169, "科罗莫特·钢尺", "铁炉堡", 68.2, 46.2, 1455 } }, e = { 6169, "科罗莫特·钢尺", "铁炉堡", 68.2, 46.2, 1455 }, note = "铁珊瑚在米奈希尔港以南(湿地 10,66)，被约 28 只鱼人团团围住，提前想好拉怪路线；可与暗黑之链任务的湿地行程顺路合并。" },
    [1709] = { n = "Klockmort's Creation", cn = "科罗莫特的成果", l = 30, r = 20, f = "A", s = { { 6169, "科罗莫特·钢尺", "铁炉堡", 68.2, 46.2, 1455 } }, e = { 6169, "科罗莫特·钢尺", "铁炉堡", 68.2, 46.2, 1455 }, items = { 6974 }, note = "属于火硬多段链的一环；其余火硬件（头/手/腿）要在完成胸甲任务后才会开放。" },
    [1710] = { n = "Sunscorched Shells", cn = "晒焦的蛋壳", l = 30, r = 20, f = "A", s = { { 6142, "玛希尔", "达纳苏斯", 59.2, 45.4, 1457 } }, e = { 6142, "玛希尔", "达纳苏斯", 59.2, 45.4, 1457 }, note = "上高台的坡道在(千针石林 14,33)，有根大图腾柱做标记；蛋就散落在高台地面上，周围 28-29 级双足飞龙不弱，近战慎入。" },
    [1711] = { n = "Mathiel's Armor", cn = "玛希尔的铠甲", l = 30, r = 20, f = "A", s = { { 6142, "玛希尔", "达纳苏斯", 59.2, 45.4, 1457 } }, e = { 6142, "玛希尔", "达纳苏斯", 59.2, 45.4, 1457 }, items = { 6973 }, note = "属于火硬多段链的一环；其余火硬件（头/手/腿）要在完成胸甲任务后才会开放。" },
    [1712] = { n = "Cyclonian", cn = "塞克隆尼亚", l = 40, r = 30, s = { { 6176, "捕风者巴斯拉", "奥特兰克山脉", 80.4, 66.8, 1416 } }, e = { 6176, "捕风者巴斯拉", "奥特兰克山脉", 80.4, 66.8, 1416 }, note = "流亡精华需在阿拉希高地的元素怪身上收集三种符咒各 8 个；荆棘谷的巨魔獠牙可与「猎杀叶尼库」共用掉落，两任务一起刷效率高。" },
    [1713] = { n = "The Summoning", cn = "召唤", l = 40, r = 30, s = { { 6176, "捕风者巴斯拉", "奥特兰克山脉", 80.4, 66.8, 1416 } }, e = { 6176, "捕风者巴斯拉", "奥特兰克山脉", 80.4, 66.8, 1416 }, note = "飓风是 40 级精英元素，伤害以自然系为主；进场先喝自然防护药水可吸收大半伤害，40 级可单挑；注意击飞，别被打下台子。" },
    [1714] = { n = "Essence of the Exile", cn = "流放精华", l = 37, r = 30, s = { { 89931, "巴斯拉斯的大锅炉", "奥特兰克山脉", 79.3, 66.7, 1416 } }, e = { 89931, "巴斯拉斯的大锅炉", "奥特兰克山脉", 79.3, 66.7, 1416 }, items = { 6851 }, note = "三种符咒分别掉自阿拉希西/北/东三处绑缚法阵附近的元素怪，掉率很好；不需要先开「被困的公主」那条链。" },
    [1715] = { n = "The Slaughtered Lamb", cn = "已宰的羔羊", l = 10, r = 10, f = "A", races = { 1, 7 }, s = { { 6120, "拉戈·黑钳", "铁炉堡", 47.6, 9.6, 1455 } }, e = { 6122, "黑暗缚灵者加科因", "暴风城", 25.4, 78.4, 1453 }, note = "这条链最终学会召唤虚空行者；召唤法阵在「宰羊」旅店地下室——下楼梯左转走到尽头，左下角还有一条很容易错过的暗道。" },
    [1716] = { n = "Devourer of Souls", cn = "噬魂者", l = 20, r = 20, f = "A", races = { 1, 7 }, s = { { 6122, "黑暗缚灵者加科因", "暴风城", 25.4, 78.4, 1453 } }, e = { 6244, "先知塔卡尔", "贫瘠之地", 49.2, 57, 1413 }, note = "目标营地(贫瘠之地 49,57)，在陶拉祖营地以东的路叉旁，穿过恐龙群看到两顶白帐篷即是；联盟玩家建议经灰谷过去，顺路开阿斯特兰纳飞行点。" },
    [1717] = { n = "Gakin's Summons", cn = "加科因的召唤", l = 20, r = 20, f = "A", races = { 1, 7 }, s = { { 6120, "拉戈·黑钳", "铁炉堡", 47.6, 9.6, 1455 } }, e = { 6122, "黑暗缚灵者加科因", "暴风城", 25.4, 78.4, 1453 }, note = "魅魔链的起始任务；从暴风城坐船到奥伯丁再走过去是最安全的路线，顺路把沿途飞行点都开了。" },
    [1718] = { n = "The Islander", cn = "岛民", l = 30, r = 30, s = { { 3041, "托姆·暴怒图腾", "雷霆崖", 57.6, 87.2, 1456 }, { 3354, "索瑞克", "奥格瑞玛", 80.2, 32.4, 1454 }, { 4595, "巴尔图斯·弗勒", "幽暗城", 47.2, 17, 1458 }, { 5113, "凯夫·重锤", "铁炉堡", 70, 90.6, 1455 }, { 5479, "武神", "暴风城", 78.8, 45.6, 1453 } }, e = { 6236, "克兰诺克·马克雷德", "贫瘠之地", 68.6, 49, 1413 }, note = "小岛在(荆棘谷 68,49)，必须从(荆棘谷 66,48)沿岸边浅滩走过去，否则会疲劳掉血；挑战者 26-27 级一个个上，间隔 15-20 秒，逐个击破即可。" },
    [1719] = { n = "The Affray", cn = "格斗考验", l = 30, r = 30, s = { { 6236, "克兰诺克·马克雷德", "贫瘠之地", 68.6, 49, 1413 } }, e = { 6236, "克兰诺克·马克雷德", "贫瘠之地", 68.6, 49, 1413 }, spells = { 2458 }, note = "挑战者每 10-15 秒上一个，血量低可用挫志怒吼控场后打绷带；大块头威尔不吃恐惧，留好爆发技能；完成学会狂暴姿态与拦截，并开启旋风武器链。" },
    [1738] = { n = "Heartswood", cn = "同心树", l = 20, r = 20, f = "A", races = { 1, 7 }, s = { { 6244, "先知塔卡尔", "贫瘠之地", 49.2, 57, 1413 } }, e = { 6122, "黑暗缚灵者加科因", "暴风城", 25.4, 78.4, 1453 }, note = "同心树在(灰谷 31,32)，先清周边再点树取物；从阿斯特兰纳一侧贴墙走过去能少打很多怪；取完回暴风城交，别交错地方。" },
    [1739] = { n = "The Binding", cn = "誓缚", l = 20, r = 20, f = "A", races = { 1, 7 }, s = { { 6122, "黑暗缚灵者加科因", "暴风城", 25.4, 78.4, 1453 } }, e = { 6122, "黑暗缚灵者加科因", "暴风城", 25.4, 78.4, 1453 }, items = { 22243 }, spells = { 712 }, note = "与虚空行者一样在旅店地下室法阵进行，用上一步取回的树心召出 20 级魅魔，让虚空行者顶在前面即可，20 级可单挑。" },
    [1740] = { n = "The Orb of Soran'ruk", cn = "索兰鲁克宝珠", l = 25, r = 20, s = { { 6247, "杜安·卡汉", "贫瘠之地", 49.2, 57.2, 1413 } }, e = { 6247, "杜安·卡汉", "贫瘠之地", 49.2, 57.2, 1413 }, items = { 6898, 15109 }, note = "记得要跑两个副本：黑暗深渊拿 3 块小碎片，影牙城堡拿 1 块大碎片，提前组好队一次跑完。" },
    [1758] = { n = "Tome of the Cabal", cn = "阴谋之书", l = 30, r = 30, f = "A", races = { 1, 7 }, s = { { 6251, "斯坦哈德·法尔杉", "贫瘠之地", 62.6, 35.4, 1413 } }, e = { 6294, "克罗姆·粗臂", "铁炉堡", 74.2, 9.8, 1455 }, note = "发霉的典籍在(丹莫罗 34,72)，取回后到铁炉堡图书馆(铁炉堡 79,4)交任务。" },
    [1778] = { n = "The Tome of Divinity", cn = "圣洁之书", l = 13, r = 12, f = "A", races = { 3 }, s = { { 6175, "约翰·特纳", "铁炉堡", 27.8, 70, 1455 } }, e = { 6179, "蒂萨·热炉", "铁炉堡", 27.4, 12, 1455 } },
    [1779] = { n = "The Tome of Divinity", cn = "圣洁之书", l = 13, r = 12, f = "A", races = { 3 }, s = { { 6179, "蒂萨·热炉", "铁炉堡", 27.4, 12, 1455 } }, e = { 6178, "穆里顿·热炉", "铁炉堡", 23.6, 8.6, 1455 }, note = "目标遗体就在孤岛小丘上(丹莫罗 78,58)，转身走几步就到。" },
    [1780] = { n = "The Tome of Divinity", cn = "圣洁之书", l = 13, r = 12, f = "A", races = { 1 }, s = { { 6174, "斯蒂芬妮·特纳", "暴风城", 57, 61.8, 1453 } }, e = { 6171, "达索瑞恩·拉尔", "暴风城", 40, 29.8, 1453 } },
    [1781] = { n = "The Tome of Divinity", cn = "圣洁之书", l = 13, r = 12, f = "A", races = { 1 }, s = { { 6171, "达索瑞恩·拉尔", "暴风城", 40, 29.8, 1453 } }, e = { 6173, "贾森·坦诺姆", "暴风城", 38.6, 26.6, 1453 } },
    [1782] = { n = "Furen's Armor", cn = "弗伦的铠甲", l = 28, r = 20, f = "A", s = { { 5413, "弗伦·长须", "暴风城", 58, 16.8, 1453 } }, e = { 5413, "弗伦·长须", "暴风城", 58, 16.8, 1453 }, items = { 6972 } },
    [1783] = { n = "The Tome of Divinity", cn = "圣洁之书", l = 13, r = 12, f = "A", races = { 3 }, s = { { 6178, "穆里顿·热炉", "铁炉堡", 23.6, 8.6, 1455 } }, e = { 6177, "纳姆·法奥克", "丹莫罗", 78.2, 58, 1426 }, note = "出门前先把炉石绑在铁炉堡或暴风城，省去横穿地图的跑路；遗体在(丹莫罗 78,58)，随后还要杀黑铁矮人取手稿。" },
    [1784] = { n = "The Tome of Divinity", cn = "圣洁之书", l = 13, r = 12, f = "A", races = { 3 }, s = { { 6177, "纳姆·法奥克", "丹莫罗", 78.2, 58, 1426 } }, e = { 6178, "穆里顿·热炉", "铁炉堡", 23.6, 8.6, 1455 }, note = "黑铁间谍就在附近区域，杀几只即掉手稿，实际掉率比描述的高，不用太担心。" },
    [1785] = { n = "The Tome of Divinity", cn = "圣洁之书", l = 13, r = 12, f = "A", races = { 3 }, s = { { 6178, "穆里顿·热炉", "铁炉堡", 23.6, 8.6, 1455 } }, e = { 6179, "蒂萨·热炉", "铁炉堡", 27.4, 12, 1455 }, spells = { 7328 } },
    [1786] = { n = "The Tome of Divinity", cn = "圣洁之书", l = 13, r = 12, f = "A", races = { 1 }, s = { { 6173, "贾森·坦诺姆", "暴风城", 38.6, 26.6, 1453 } }, e = { 6172, "亨兹·法奥克", "艾尔文森林", 72.6, 51.4, 1429 }, note = "亨泽·福克(艾尔文森林 72,51)；附近的迪菲亚都能单独拉出来打，难度不高。" },
    [1787] = { n = "The Tome of Divinity", cn = "圣洁之书", l = 13, r = 12, f = "A", races = { 1 }, s = { { 6172, "亨兹·法奥克", "艾尔文森林", 72.6, 51.4, 1429 } }, e = { 6173, "贾森·坦诺姆", "暴风城", 38.6, 26.6, 1453 }, note = "迪菲亚叛徒法师就在暴风城南门外镜湖边，杀一两只基本就掉手稿。" },
    [1788] = { n = "The Tome of Divinity", cn = "圣洁之书", l = 13, r = 12, f = "A", races = { 1 }, s = { { 6173, "贾森·坦诺姆", "暴风城", 38.6, 26.6, 1453 } }, e = { 6171, "达索瑞恩·拉尔", "暴风城", 40, 29.8, 1453 }, spells = { 7328 } },
    [1789] = { n = "The Symbol of Life", cn = "生命符记", l = 12, r = 12, f = "A", races = { 3 }, s = { { 6179, "蒂萨·热炉", "铁炉堡", 27.4, 12, 1455 } }, e = { 6179, "蒂萨·热炉", "铁炉堡", 27.4, 12, 1455 }, items = { 6866 }, note = "若任务道具中途丢失，可找铁炉堡的蒂莎·战炉免费再领一次，无额外要求。" },
    [1790] = { n = "The Symbol of Life", cn = "生命符记", l = 12, r = 12, f = "A", races = { 1 }, s = { { 6171, "达索瑞恩·拉尔", "暴风城", 40, 29.8, 1453 } }, e = { 6171, "达索瑞恩·拉尔", "暴风城", 40, 29.8, 1453 }, items = { 6866 }, note = "人类版：任务道具丢了可回暴风城大教堂找杜索瑞安·拉尔再领一次。" },
    [1791] = { n = "The Windwatcher", cn = "捕风者", l = 30, r = 30, s = { { 6236, "克兰诺克·马克雷德", "贫瘠之地", 68.6, 49, 1413 } }, e = { 6176, "捕风者巴斯拉", "奥特兰克山脉", 80.4, 66.8, 1416 }, note = "观察者巴思兰(奥特兰克山脉 81,67)：从希尔斯布莱德丘陵沿河一路向北进奥特兰克即到，比走大路绕过怪群轻松。" },
    [1792] = { n = "Whirlwind Weapon", cn = "旋风武器", l = 40, r = 30, s = { { 6176, "捕风者巴斯拉", "奥特兰克山脉", 80.4, 66.8, 1416 } }, e = { 6176, "捕风者巴斯拉", "奥特兰克山脉", 80.4, 66.8, 1416 }, items = { 6975, 6977, 6976 }, note = "需先完成狂暴姿态两步（岛民与格斗考验）才可接；新武器熟练度练满只要十来分钟，不用愁。" },
    [1793] = { n = "The Tome of Valor", cn = "勇气之书", l = 20, r = 20, f = "A", s = { { 6171, "达索瑞恩·拉尔", "暴风城", 40, 29.8, 1453 } }, e = { 6171, "达索瑞恩·拉尔", "暴风城", 40, 29.8, 1453 }, items = { 6776 }, note = "从暴风城大教堂的杜索瑞安·拉尔处领取，头顶是蓝问号而非黄色感叹号，别错过；中途放弃可回上一步任务的 NPC 重新接。" },
    [1794] = { n = "The Tome of Valor", cn = "勇气之书", l = 20, r = 20, f = "A", s = { { 6179, "蒂萨·热炉", "铁炉堡", 27.4, 12, 1455 } }, e = { 6179, "蒂萨·热炉", "铁炉堡", 27.4, 12, 1455 }, items = { 6776 } },
    [1795] = { n = "The Binding", cn = "誓缚", l = 30, r = 30, s = { { 6251, "斯坦哈德·法尔杉", "贫瘠之地", 62.6, 35.4, 1413 } }, e = { 6251, "斯坦哈德·法尔杉", "贫瘠之地", 62.6, 35.4, 1413 }, items = { 22244 }, spells = { 691 }, note = "召唤点在棘齿城飞行点上方的术士帐篷内；战斗中可以同时带着自己的宠物打（这只恶魔不算你的召唤物）；失败就放弃任务回斯特拉汗·法尔桑处重接。" },
    [1796] = { n = "Components for the Enchanted Gold Bloodrobe", cn = "魔化金线血袍", l = 31, r = 31, s = { { 6266, "梅纳拉·沃伦德", "贫瘠之地", 62.4, 35.4, 1413 } }, e = { 6266, "梅纳拉·沃伦德", "贫瘠之地", 62.4, 35.4, 1413 }, note = "奥法长袍需裁缝制作，图纸稀有，拍卖行买更省事；部落交任务时顺带带根金条去藏宝海湾可接后续；自己刷的话去黑海岸北边塔楼打暗黑教派虚空行者，掉率约 1.25% 要有耐心。" },
    [1798] = { n = "Seeking Strahad", cn = "寻找斯坦哈德", l = 30, r = 30, f = "A", races = { 1, 7 }, s = { { 6122, "黑暗缚灵者加科因", "暴风城", 25.4, 78.4, 1453 } }, e = { 6251, "斯坦哈德·法尔杉", "贫瘠之地", 62.6, 35.4, 1413 }, note = "这步以跑路为主，先把沿线飞行点全部开好会轻松很多。" },
    [1799] = { n = "Fragments of the Orb of Orahil", cn = "宝珠碎片", l = 40, r = 35, s = { { 6266, "梅纳拉·沃伦德", "贫瘠之地", 62.4, 35.4, 1413 } }, e = { 6546, "塔贝萨", "尘泥沼泽", 46, 57, 1445 }, note = "地狱火宝珠并非出自地狱火，而是灼刃召唤者掉落；拿到宝珠后必须先去塔贝萨的屋子(尘泥沼泽 46,57)再继续，顺序错了要重跑。" },
    [1801] = { n = "Tome of the Cabal", cn = "阴谋之书", l = 30, r = 30, f = "H", races = { 2, 5, 8 }, s = { { 6251, "斯坦哈德·法尔杉", "贫瘠之地", 62.6, 35.4, 1413 } }, e = { 6293, "约拉·安尼森", "幽暗城", 76, 37.6, 1458 }, note = "起始 NPC 在幽暗城魔法区对面的店铺里(幽暗城 76,38)。" },
    [1802] = { n = "Tome of the Cabal", cn = "阴谋之书", l = 30, r = 30, f = "A", races = { 1, 7 }, s = { { 6294, "克罗姆·粗臂", "铁炉堡", 74.2, 9.8, 1455 } }, e = { 6294, "克罗姆·粗臂", "铁炉堡", 74.2, 9.8, 1455 }, note = "破烂的手稿在洞穴深处(千针石林 43,33)，进洞右转沿环线走；发霉的典籍在海边鱼人营地的棚屋(希尔斯布莱德丘陵 28,73)；推荐放风筝打法：派虚空行者进营地拿，血薄时牺牲它直接跑路。" },
    [1803] = { n = "Tome of the Cabal", cn = "阴谋之书", l = 30, r = 30, f = "H", races = { 2, 5, 8 }, s = { { 6293, "约拉·安尼森", "幽暗城", 76, 37.6, 1458 } }, e = { 6293, "约拉·安尼森", "幽暗城", 76, 37.6, 1458 } },
    [1804] = { n = "Tome of the Cabal", cn = "阴谋之书", l = 30, r = 30, f = "A", races = { 1, 7 }, s = { { 6294, "克罗姆·粗臂", "铁炉堡", 74.2, 9.8, 1455 } }, e = { 6251, "斯坦哈德·法尔杉", "贫瘠之地", 62.6, 35.4, 1413 }, note = "掉杖的龙喉施法怪在(湿地 49,45)的怒牙营地，影卫几只内基本必出，很好打。" },
    [1805] = { n = "Tome of the Cabal", cn = "阴谋之书", l = 30, r = 30, f = "H", races = { 2, 5, 8 }, s = { { 6293, "约拉·安尼森", "幽暗城", 76, 37.6, 1458 } }, e = { 6251, "斯坦哈德·法尔杉", "贫瘠之地", 62.6, 35.4, 1413 }, note = "龙喉兽人在怒牙营地(湿地 51,45)：从阿拉希的落锤镇沿路南下进湿地，营地后门(湿地 51,45)进入最近；注意只有施法系怪掉任务杖。" },
    [1806] = { n = "The Test of Righteousness", cn = "正义试炼", l = 22, r = 20, f = "A", races = { 1, 3 }, s = { { 6181, "乔丹·斯迪威尔", "丹莫罗", 52.4, 36.8, 1426 } }, e = { 6181, "乔丹·斯迪威尔", "丹莫罗", 52.4, 36.8, 1426 }, items = { 6953 }, note = "20 级圣骑士的经典任务，需要跑三个副本，工作量不小，但完成后的武器用到 30 级都不过时。" },
    [1818] = { n = "Speak with Dillinger", cn = "迪林格尔", l = 10, r = 10, f = "H", s = { { 2131, "奥斯蒂尔·德·蒙", "提瑞斯法林地", 61.8, 52.4, 1420 } }, e = { 1496, "亡灵卫兵迪林格尔", "提瑞斯法林地", 58.2, 51.4, 1420 }, note = "部落战士专属链的起始 NPC(提瑞斯法林地-布瑞尔 58,51)。" },
    [1819] = { n = "Ulag the Cleaver", cn = "切割者奥拉格", l = 10, r = 10, f = "H", s = { { 1496, "亡灵卫兵迪林格尔", "提瑞斯法林地", 58.2, 51.4, 1420 } }, e = { 1496, "亡灵卫兵迪林格尔", "提瑞斯法林地", 58.2, 51.4, 1420 }, spells = { 71 }, note = "在迪林格尔北边的墓园里，墓冢前道路左侧地上有块骷髅石板，点击即开墓门放怪；小心巡逻的精英卫兵抢先击杀导致任务不计完成。" },
    [1820] = { n = "Speak with Coleman", cn = "库勒曼", l = 10, r = 10, f = "H", s = { { 1496, "亡灵卫兵迪林格尔", "提瑞斯法林地", 58.2, 51.4, 1420 } }, e = { 1500, "库勒曼·法席恩", "提瑞斯法林地", 61.8, 52.4, 1420 }, note = "库勒曼在绞刑架酒馆里、旅店老板蕾妮对面，近了小地图上就能看到问号。" },
    [1821] = { n = "Agamand Heirlooms", cn = "阿加曼德家传武器", l = 11, r = 10, f = "H", s = { { 1500, "库勒曼·法席恩", "提瑞斯法林地", 61.8, 52.4, 1420 } }, e = { 1500, "库勒曼·法席恩", "提瑞斯法林地", 61.8, 52.4, 1420 }, note = "墓穴入口(提瑞斯法林地 52,27)，任务物品就放在墓穴内的武器架上；拉怪最多一次三只，多用断筋减速拉开打，10 级可单刷。" },
    [1822] = { n = "Heirloom Weapon", cn = "祖传武器", l = 11, r = 10, f = "H", s = { { 1500, "库勒曼·法席恩", "提瑞斯法林地", 61.8, 52.4, 1420 } }, e = { 1500, "库勒曼·法席恩", "提瑞斯法林地", 61.8, 52.4, 1420 }, items = { 7115, 7117, 7116, 7118 } },
    [1823] = { n = "Speak with Ruga", cn = "和鲁迦交谈", l = 20, r = 20, f = "H", s = { { 3041, "托姆·暴怒图腾", "雷霆崖", 57.6, 87.2, 1456 }, { 3354, "索瑞克", "奥格瑞玛", 80.2, 32.4, 1454 }, { 4595, "巴尔图斯·弗勒", "幽暗城", 47.2, 17, 1458 } }, e = { 6394, "鲁迦·暴怒图腾", "贫瘠之地", 44.6, 59.4, 1413 }, note = "鲁加·怒图(贫瘠之地-陶拉祖营地 44,59)；这是部落战士长链的起点，组固定队做完能拿到不错的 20 级护甲，单刷会拖很久。" },
    [1824] = { n = "Trial at the Field of Giants", cn = "巨人旷野的试炼", l = 20, r = 20, f = "H", s = { { 6394, "鲁迦·暴怒图腾", "贫瘠之地", 44.6, 59.4, 1413 } }, e = { 6394, "鲁迦·暴怒图腾", "贫瘠之地", 44.6, 59.4, 1413 }, items = { 7120 }, note = "优先杀东侧(贫瘠之地 48,70)的爬行者，别碰蜂群怪（死后会分裂出小怪）；触须离体约 15 分钟内有效，抓紧时间；可与十字路口的「找蛋」顺路一起做。" },
    [1825] = { n = "Speak with Thun'grim", cn = "和索恩格瑞姆交谈", l = 20, r = 20, f = "H", s = { { 6394, "鲁迦·暴怒图腾", "贫瘠之地", 44.6, 59.4, 1413 } }, e = { 5878, "索恩格瑞姆·火眼", "贫瘠之地", 57.2, 30.2, 1413 }, note = "他在山顶(贫瘠之地 57,30)，最佳上山路线从(贫瘠之地 54,28)开始；别钻到山下的矿洞和塔楼营地里找。" },
    [1838] = { n = "Brutal Armor", cn = "野蛮护甲", l = 30, r = 20, f = "H", s = { { 5878, "索恩格瑞姆·火眼", "贫瘠之地", 57.2, 30.2, 1413 } }, e = { 5878, "索恩格瑞姆·火眼", "贫瘠之地", 57.2, 30.2, 1413 }, note = "烟熏铁锭在石爪山脉的矿洞(石爪山脉 74,60)，杀狗头人即掉，20 余级可单刷；完成后开放护手/胸甲/腿甲/头盔四条子任务。" },
    [1839] = { n = "Ula'elek and the Brutal Gauntlets", cn = "尤拉莱克和野蛮护手", l = 30, r = 20, f = "H", s = { { 5878, "索恩格瑞姆·火眼", "贫瘠之地", 57.2, 30.2, 1413 } }, e = { 6408, "尤拉莱克", "杜隆塔尔", 56.2, 74.4, 1411 }, note = "尤拉莱克在森金村(杜隆塔尔-森金村 56,75)。" },
    [1840] = { n = "Orm Stonehoof and the Brutal Helm", cn = "奥姆·石蹄和野蛮头盔", l = 30, r = 20, f = "H", s = { { 5878, "索恩格瑞姆·火眼", "贫瘠之地", 57.2, 30.2, 1413 } }, e = { 6410, "奥姆·石蹄", "雷霆崖", 39, 55.8, 1456 }, note = "完成野蛮胸甲后找山顶的奥姆·石蹄接；低级阶段战士头部装备稀缺，这条值得做。" },
    [1841] = { n = "Velora Nitely and the Brutal Legguards", cn = "维罗拉·奈特雷和野蛮腿甲", l = 30, r = 20, f = "H", s = { { 5878, "索恩格瑞姆·火眼", "贫瘠之地", 57.2, 30.2, 1413 } }, e = { 6411, "维罗拉·奈特雷", "幽暗城", 62.4, 39.2, 1458 }, note = "维罗拉在湿地一侧：从塔伦米尔沿大路穿阿拉希过去，路相对安全，沿线注意猛禽龙。" },
    [1842] = { n = "Satyr Hooves", cn = "萨特之蹄", l = 30, r = 20, f = "H", s = { { 6408, "尤拉莱克", "杜隆塔尔", 56.2, 74.4, 1411 } }, e = { 6408, "尤拉莱克", "杜隆塔尔", 56.2, 74.4, 1411 }, note = "恶魔蹄甲由萨特纳尔的萨特掉落，掉率接近 100%，沿营地边缘逐只引杀即可。" },
    [1843] = { n = "Brutal Gauntlets", cn = "野蛮护手", l = 30, r = 20, f = "H", s = { { 6408, "尤拉莱克", "杜隆塔尔", 56.2, 74.4, 1411 } }, e = { 6408, "尤拉莱克", "杜隆塔尔", 56.2, 74.4, 1411 }, items = { 7129 } },
    [1844] = { n = "Chimaeric Horn", cn = "奇美拉之角", l = 30, r = 20, f = "H", s = { { 6410, "奥姆·石蹄", "雷霆崖", 39, 55.8, 1456 } }, e = { 6410, "奥姆·石蹄", "雷霆崖", 39, 55.8, 1456 }, note = "奇美拉母兽在焦痕谷南侧山壁一带游荡，体型比幼兽大一圈，比较好认。" },
    [1845] = { n = "Brutal Helm", cn = "野蛮头盔", l = 30, r = 20, f = "H", s = { { 6410, "奥姆·石蹄", "雷霆崖", 39, 55.8, 1456 } }, e = { 6410, "奥姆·石蹄", "雷霆崖", 39, 55.8, 1456 }, items = { 7130 }, note = "低级阶段头部装备稀缺，这个头盔值得拿；此链仅限战士，圣骑士接不了。" },
    [1846] = { n = "Dragonmaw Shinbones", cn = "龙喉胫骨", l = 30, r = 20, f = "H", s = { { 6411, "维罗拉·奈特雷", "幽暗城", 62.4, 39.2, 1458 } }, e = { 6411, "维罗拉·奈特雷", "幽暗城", 62.4, 39.2, 1458 }, note = "龙喉兽人在湿地中部、阿拉希以南过桥后的山脚下；胫骨掉落后要右键测试坚固度，并非每根合格，多备几根。" },
    [1847] = { n = "Brutal Legguards", cn = "野蛮腿甲", l = 30, r = 20, f = "H", s = { { 6411, "维罗拉·奈特雷", "幽暗城", 62.4, 39.2, 1458 } }, e = { 6411, "维罗拉·奈特雷", "幽暗城", 62.4, 39.2, 1458 }, items = { 7132 } },
    [1848] = { n = "Brutal Hauberk", cn = "野蛮锁甲", l = 30, r = 20, f = "H", s = { { 5878, "索恩格瑞姆·火眼", "贫瘠之地", 57.2, 30.2, 1413 } }, e = { 5878, "索恩格瑞姆·火眼", "贫瘠之地", 57.2, 30.2, 1413 }, items = { 7133 }, note = "完成后开放头盔/护手/腿甲三条后续，是整条野蛮护甲链的枢纽步骤。" },
    [1858] = { n = "The Shattered Hand", cn = "碎手氏族", l = 13, r = 10, f = "H", races = { 2, 8 }, s = { { 6446, "瑟祖克", "奥格瑞玛", 42.8, 53.4, 1454 } }, e = { 6446, "瑟祖克", "奥格瑞玛", 42.8, 53.4, 1454 }, items = { 7298 }, note = "钥匙靠在奥格瑞玛旅店里对加蒙使用「偷窃」获得；备一套盗贼工具直接开锁也行（开锁 16 级才能学）。" },
    [1859] = { n = "Therzok", cn = "瑟祖克", l = 10, r = 10, f = "H", races = { 2, 8 }, s = { { 3170, "卡普拉克", "杜隆塔尔", 52, 43.6, 1411 } }, e = { 6446, "瑟祖克", "奥格瑞玛", 42.8, 53.4, 1454 }, note = "亡灵/巨魔盗贼接不到这步可跳过——直接去奥格瑞玛暗影裂口找下一位 NPC 继续链。" },
    [1860] = { n = "Speak with Jennea", cn = "和詹妮亚交谈", l = 10, r = 10, f = "A", races = { 1, 7, 95 }, s = { { 328, "扎尔迪玛·维夫希尔特", "艾尔文森林", 43.2, 66.2, 1429 } }, e = { 5497, "詹妮亚·坎农", "暴风城", 38.6, 79.4, 1453 }, note = "前往暴风城法师区的巫师圣殿找詹妮亚交谈。" },
    [1861] = { n = "Mirror Lake", cn = "明镜湖", l = 10, r = 10, f = "A", races = { 1, 7, 95 }, s = { { 5497, "詹妮亚·坎农", "暴风城", 38.6, 79.4, 1453 } }, e = { 5497, "詹妮亚·坎农", "暴风城", 38.6, 79.4, 1453 }, items = { 7508, 9513 }, note = "明镜湖在(艾尔文森林 29,61)。" },
    [1879] = { n = "Speak with Bink", cn = "和彬克交谈", l = 10, r = 10, f = "A", races = { 1, 7 }, s = { { 1228, "玛济斯·石衣", "丹莫罗", 47.4, 52, 1426 } }, e = { 5144, "彬克", "铁炉堡", 27, 8.2, 1455 } },
    [1880] = { n = "Mage-tastic Gizmonitor", cn = "法师文档存储器", l = 10, r = 10, f = "A", races = { 1, 7 }, s = { { 5144, "彬克", "铁炉堡", 27, 8.2, 1455 } }, e = { 5144, "彬克", "铁炉堡", 27, 8.2, 1455 }, items = { 7507, 9514 }, note = "文档存储器在带电梯那栋楼的一层、桌子下面的工具箱里(丹莫罗 27,36)。" },
    [1881] = { n = "Speak with Anastasia", cn = "安娜斯塔西娅", l = 10, r = 10, f = "H", races = { 5, 8 }, s = { { 2128, "凯恩·火歌", "提瑞斯法林地", 61.8, 52.4, 1420 } }, e = { 4568, "安娜斯塔西娅·哈特威尔", "幽暗城", 85, 10.2, 1458 }, note = "安娜斯塔西娅在幽暗城(幽暗城 85,10)；就算跳过这步，后续任务也能直接接。" },
    [1882] = { n = "The Balnir Farmstead", cn = "巴尼尔农场", l = 10, r = 10, f = "H", races = { 5, 8 }, s = { { 4568, "安娜斯塔西娅·哈特威尔", "幽暗城", 85, 10.2, 1458 } }, e = { 4568, "安娜斯塔西娅·哈特威尔", "幽暗城", 85, 10.2, 1458 }, items = { 7507, 9514 }, note = "巴尼尔农场在布瑞尔以东(提瑞斯法林地 76,60)；要找的巴尼尔骄花其实在药草园里，别在农舍里翻。" },
    [1883] = { n = "Speak with Un'thuwa", cn = "安苏瓦", l = 10, r = 10, f = "H", races = { 2, 5, 8 }, s = { { 3049, "瑟斯顿·科萨恩", "雷霆崖", 25, 20.6, 1456 }, { 7311, "尤塞尔奈", "奥格瑞玛", 39, 86, 1454 } }, e = { 5880, "安苏瓦", "杜隆塔尔", 56.2, 75, 1411 } },
    [1884] = { n = "Ju-Ju Heaps", cn = "魂能骨堆", l = 10, r = 10, f = "H", races = { 2, 5, 8 }, s = { { 5880, "安苏瓦", "杜隆塔尔", 56.2, 75, 1411 } }, e = { 5880, "安苏瓦", "杜隆塔尔", 56.2, 75, 1411 }, items = { 7508, 9513 }, note = "骨堆在扎拉赞恩小岛的棚屋里——他旁边两间、营地以北还有几处；外形和普通骷髅堆一样，区别是能点击。" },
    [1885] = { n = "Mennet Carkad", cn = "米奈特·卡加德", l = 10, r = 10, f = "H", races = { 5 }, s = { { 2130, "马里恩·考尔", "提瑞斯法林地", 61.6, 52, 1420 } }, e = { 6467, "米奈特·卡加德", "幽暗城", 83.2, 69, 1458 }, note = "亡灵盗贼专属任务。" },
    [1886] = { n = "The Deathstalkers", cn = "亡灵哨兵", l = 13, r = 10, f = "H", races = { 5 }, s = { { 6467, "米奈特·卡加德", "幽暗城", 83.2, 69, 1458 } }, e = { 6467, "米奈特·卡加德", "幽暗城", 83.2, 69, 1458 }, note = "目标沿幽暗城与银松森林之间的大路来回巡逻，12-14 级即可单杀，备点恢复品。" },
    [1898] = { n = "The Deathstalkers", cn = "亡灵哨兵", l = 13, r = 10, f = "H", races = { 5 }, s = { { 6467, "米奈特·卡加德", "幽暗城", 83.2, 69, 1458 } }, e = { 6522, "安德隆·甘特", "幽暗城", 54.8, 75.6, 1458 }, note = "目标在幽暗城药剂区(幽暗城 55,76)。" },
    [1899] = { n = "The Deathstalkers", cn = "亡灵哨兵", l = 13, r = 10, f = "H", races = { 5 }, s = { { 6522, "安德隆·甘特", "幽暗城", 54.8, 75.6, 1458 } }, e = { 6467, "米奈特·卡加德", "幽暗城", 83.2, 69, 1458 }, note = "记得从他身后的书架把书拿了再走；组队状态下书架可能无法互动，单人去做最稳。" },
    [1919] = { n = "Report to Jennea", cn = "向詹妮亚报告", l = 15, r = 15, f = "A", races = { 1, 7, 95 }, s = { { 328, "扎尔迪玛·维夫希尔特", "艾尔文森林", 43.2, 66.2, 1429 }, { 7312, "丁克", "铁炉堡", 26.8, 8.4, 1455 } }, e = { 5497, "詹妮亚·坎农", "暴风城", 38.6, 79.4, 1453 }, note = "詹妮亚在法师区高塔顶端(暴风城 38,79)：沿塔侧螺旋梯上去，蓝地毯尽头穿过传送门即到。" },
    [1920] = { n = "Investigate the Blue Recluse", cn = "调查蓝色隐士", l = 16, r = 15, f = "A", races = { 1, 7, 95 }, s = { { 5497, "詹妮亚·坎农", "暴风城", 38.6, 79.4, 1453 } }, e = { 5497, "詹妮亚·坎农", "暴风城", 38.6, 79.4, 1453 }, note = "去地下室用咒语只会召出一只，在一层用会同时召三只；稳妥打法是每杀一只就换到厨房壁炉里再施咒，逐只收拾。" },
    [1921] = { n = "Gathering Materials", cn = "收集原料", l = 15, r = 15, f = "A", races = { 1, 7, 95 }, s = { { 5497, "詹妮亚·坎农", "暴风城", 38.6, 79.4, 1453 } }, e = { 1309, "维恩·拉尔森", "暴风城", 41.6, 76.6, 1453 }, note = "矿洞在(洛克莫丹 35,18)：外围怪 10-12 级、洞内 12-14；洞里的地卜师会开火焰屏障，火法注意会被免疫。" },
    [1938] = { n = "Ur's Treatise on Shadow Magic", cn = "乌尔的暗影魔法研究论文", l = 28, r = 26, f = "A", races = { 1, 7, 95 }, s = { { 5694, "高阶巫师安多玛斯", "暴风城", 37.6, 81.6, 1453 } }, e = { 5694, "高阶巫师安多玛斯", "暴风城", 37.6, 81.6, 1453 }, note = "不必杀塔顶的摩根斯：沿坡道靠左上顶层，书就在坡道左侧书架上，避开他身边的怪拿了就走；洞里的狗会烧蓝，注意留蓝。" },
    [1939] = { n = "High Sorcerer Andromath", cn = "高阶巫师安多玛斯", l = 26, r = 26, f = "A", races = { 1, 7, 95 }, s = { { 5144, "彬克", "铁炉堡", 27, 8.2, 1455 }, { 5497, "詹妮亚·坎农", "暴风城", 38.6, 79.4, 1453 } }, e = { 5694, "高阶巫师安多玛斯", "暴风城", 37.6, 81.6, 1453 }, note = "安多玛斯就在法师训练师传送门出来不远处(暴风城 38,82)。" },
    [1940] = { n = "Pristine Spider Silk", cn = "新鲜的蜘蛛丝", l = 26, r = 26, f = "A", races = { 1, 7, 95 }, s = { { 5694, "高阶巫师安多玛斯", "暴风城", 37.6, 81.6, 1453 } }, e = { 1309, "维恩·拉尔森", "暴风城", 41.6, 76.6, 1453 } },
    [1941] = { n = "Manaweave Robe", cn = "法纹长袍", l = 15, r = 15, f = "A", s = { { 1309, "维恩·拉尔森", "暴风城", 41.6, 76.6, 1453 } }, e = { 1309, "维恩·拉尔森", "暴风城", 41.6, 76.6, 1453 }, items = { 7509 }, note = "15 级可接；银流矿洞的怪对同级不弱且刷新快，常有其他玩家同场，组队更稳。" },
    [1942] = { n = "Astral Knot Garment", cn = "星结之衣", l = 26, r = 26, f = "A", s = { { 1309, "维恩·拉尔森", "暴风城", 41.6, 76.6, 1453 } }, e = { 1309, "维恩·拉尔森", "暴风城", 41.6, 76.6, 1453 }, items = { 7511, 9516 }, note = "需 26 级才能接；交完上一步的完美蛛丝稍等片刻，NPC 会主动给出这一步。" },
    [1943] = { n = "Speak with Deino", cn = "巨魔法师迪诺", l = 26, r = 26, f = "H", races = { 2, 5, 8 }, s = { { 4568, "安娜斯塔西娅·哈特威尔", "幽暗城", 85, 10.2, 1458 } }, e = { 5885, "迪诺", "奥格瑞玛", 38.4, 85.8, 1454 }, note = "迪诺在奥格瑞玛急救训练师旁(奥格瑞玛 38,86)；跳过这步也能直接接后续，但顺手做多点经验。" },
    [1944] = { n = "Waters of Xavian", cn = "克萨维亚之水", l = 26, r = 26, f = "H", races = { 2, 5, 8 }, s = { { 5885, "迪诺", "奥格瑞玛", 38.4, 85.8, 1454 } }, e = { 5885, "迪诺", "奥格瑞玛", 38.4, 85.8, 1454 }, note = "取水点在(灰谷 76,41)：沿碎木岗哨以北的河道走到双河交汇的瀑布下，进到最深处贴墙才能采集；别往东深入萨特纳尔。" },
    [1945] = { n = "Laughing Sisters", cn = "欢笑的姐妹", l = 26, r = 26, f = "H", races = { 2, 5, 8 }, s = { { 5885, "迪诺", "奥格瑞玛", 38.4, 85.8, 1454 } }, e = { 3484, "基尔哈拉", "贫瘠之地", 52.2, 31.6, 1413 }, note = "笑姐妹在(灰谷 58,50)，对冰霜法术抗性很高，冰法要有心理准备。" },
    [1946] = { n = "Nether-lace Garment", cn = "虚灵长袍", l = 26, r = 26, f = "H", s = { { 3484, "基尔哈拉", "贫瘠之地", 52.2, 31.6, 1413 } }, e = { 3484, "基尔哈拉", "贫瘠之地", 52.2, 31.6, 1413 }, items = { 7512, 9515 } },
    [1947] = { n = "Journey to the Marsh", cn = "沼泽之旅", l = 38, r = 30, s = { { 3048, "奥松·格鲁尔", "雷霆崖", 25.6, 14.6, 1456 }, { 4568, "安娜斯塔西娅·哈特威尔", "幽暗城", 85, 10.2, 1458 }, { 5144, "彬克", "铁炉堡", 27, 8.2, 1455 }, { 5497, "詹妮亚·坎农", "暴风城", 38.6, 79.4, 1453 }, { 5885, "迪诺", "奥格瑞玛", 38.4, 85.8, 1454 } }, e = { 6546, "塔贝萨", "尘泥沼泽", 46, 57, 1445 }, note = "塔贝萨的小屋(尘泥沼泽 46,57)：从塞拉摩沿大路南下，看到左侧残破石塔后转入小路即到。" },
    [1948] = { n = "Items of Power", cn = "强大的物品", l = 40, r = 30, s = { { 6546, "塔贝萨", "尘泥沼泽", 46, 57, 1445 } }, e = { 6546, "塔贝萨", "尘泥沼泽", 46, 57, 1445 }, note = "法杖最终任务需要同时完成本链与《隐藏的秘密》：先集 10 根荆棘部族图腾棍，再按顺序到阿拉希的指定法阵组合。" },
    [1949] = { n = "Hidden Secrets", cn = "隐藏的秘密", l = 38, r = 30, s = { { 6546, "塔贝萨", "尘泥沼泽", 46, 57, 1445 } }, e = { 6548, "大法师提尔斯", "千针石林", 78.2, 75.8, 1441 }, note = "出发前先在法师训练师处接前置《前往沼泽》，否则塔贝萨不与你对话；顺路在村子里开好飞行点。" },
    [1950] = { n = "Get the Scoop", cn = "解封咒语", l = 30, r = 30, s = { { 6548, "大法师提尔斯", "千针石林", 78.2, 75.8, 1441 } }, e = { 6548, "大法师提尔斯", "千针石林", 78.2, 75.8, 1441 }, note = "目标是一只小鸡：点击它后做「招手」动作就会变回人形，对话拿口令；它在赛道塔楼脚下(塔纳利斯 57,77)。" },
    [1951] = { n = "Rituals of Power", cn = "能量仪祭", l = 40, r = 30, s = { { 6548, "大法师提尔斯", "千针石林", 78.2, 75.8, 1441 } }, e = { 6546, "塔贝萨", "尘泥沼泽", 46, 57, 1445 }, note = "书在血色修道院图书馆，最终 Boss 前最后走廊的矮墙书架上；44 级可小心单刷，备几瓶隐身药水更稳。" },
    [1952] = { n = "Mage's Wand", cn = "法师的魔杖", l = 40, r = 30, s = { { 6546, "塔贝萨", "尘泥沼泽", 46, 57, 1445 } }, e = { 6546, "塔贝萨", "尘泥沼泽", 46, 57, 1445 }, items = { 7514, 11263, 7513 }, note = "需完成本链与《强大的物品》两条链后，塔贝萨才会开放法杖合成；她位置偏僻，提前开好飞行点。" },
    [1953] = { n = "Return to the Marsh", cn = "返回沼泽", l = 40, r = 35, s = { { 3048, "奥松·格鲁尔", "雷霆崖", 25.6, 14.6, 1456 }, { 4568, "安娜斯塔西娅·哈特威尔", "幽暗城", 85, 10.2, 1458 }, { 5144, "彬克", "铁炉堡", 27, 8.2, 1455 }, { 5497, "詹妮亚·坎农", "暴风城", 38.6, 79.4, 1453 }, { 5885, "迪诺", "奥格瑞玛", 38.4, 85.8, 1454 } }, e = { 6546, "塔贝萨", "尘泥沼泽", 46, 57, 1445 }, note = "部落版由任意法师训练师发放，30 级可接；塔贝萨的小屋在(尘泥沼泽 46,57)。" },
    [1954] = { n = "The Infernal Orb", cn = "地狱火宝珠", l = 40, r = 35, s = { { 6546, "塔贝萨", "尘泥沼泽", 46, 57, 1445 } }, e = { 6546, "塔贝萨", "尘泥沼泽", 46, 57, 1445 }, note = "目标怪在玛诺洛克集会所以东、暗屏村以东一带游荡，宝珠掉率接近必掉；路程较远，提前规划好路线。" },
    [1955] = { n = "The Exorcism", cn = "驱除魔鬼", l = 40, r = 35, s = { { 6546, "塔贝萨", "尘泥沼泽", 46, 57, 1445 } }, e = { 6546, "塔贝萨", "尘泥沼泽", 46, 57, 1445 }, note = "恶魔是 40 级精英，38-40 级法师可单挑：全程保持法力盾，蓝空就用冰环+闪现拉开读回蓝，逐段磨死。" },
    [1956] = { n = "Power in Uldaman", cn = "奥达曼的能量源", l = 40, r = 35, s = { { 6546, "塔贝萨", "尘泥沼泽", 46, 57, 1445 } }, e = { 6546, "塔贝萨", "尘泥沼泽", 46, 57, 1445 }, note = "能量源由黑曜石哨兵掉落(荒芜之地 67,44)，在奥达曼后门的山洞里；42 级精英，血量 75/50/25% 会分裂小怪且带魔法反射，血线降到节点前收手，先清小怪再爆发。" },
    [1957] = { n = "Mana Surges", cn = "法力怒灵", l = 40, r = 35, s = { { 6546, "塔贝萨", "尘泥沼泽", 46, 57, 1445 } }, e = { 6546, "塔贝萨", "尘泥沼泽", 46, 57, 1445 }, note = "法力涌动怪在屋外刷新很快，引一只不会带动其他，40 级非精英可单刷，逐只杀带休息。" },
    [1958] = { n = "Celestial Power", cn = "苍穹之力", l = 40, r = 35, s = { { 6546, "塔贝萨", "尘泥沼泽", 46, 57, 1445 } }, e = { 6546, "塔贝萨", "尘泥沼泽", 46, 57, 1445 }, items = { 7515, 9517 } },
    [1959] = { n = "Report to Anastasia", cn = "向安娜斯塔西娅报告", l = 15, r = 15, f = "H", races = { 2, 5, 8 }, s = { { 2128, "凯恩·火歌", "提瑞斯法林地", 61.8, 52.4, 1420 }, { 3049, "瑟斯顿·科萨恩", "雷霆崖", 25, 20.6, 1456 }, { 7311, "尤塞尔奈", "奥格瑞玛", 39, 86, 1454 } }, e = { 4568, "安娜斯塔西娅·哈特威尔", "幽暗城", 85, 10.2, 1458 }, note = "交付点在幽暗城(幽暗城 84,10)。" },
    [1960] = { n = "Investigate the Alchemist Shop", cn = "调查炼金店", l = 16, r = 15, f = "H", races = { 2, 5, 8 }, s = { { 4568, "安娜斯塔西娅·哈特威尔", "幽暗城", 85, 10.2, 1458 } }, e = { 4568, "安娜斯塔西娅·哈特威尔", "幽暗城", 85, 10.2, 1458 }, note = "站在台阶上使用卷轴，其中一只鬼魂会刷得离你最近：冰环控住后跑开把其余引走，回来逐只收拾；记得先在 NPC 旁领容器与显形咒语。" },
    [1961] = { n = "Gathering Materials", cn = "收集原料", l = 15, r = 15, f = "H", races = { 2, 5, 8 }, s = { { 4568, "安娜斯塔西娅·哈特威尔", "幽暗城", 85, 10.2, 1458 } }, e = { 4576, "乔瑟夫·格里高利", "幽暗城", 70.6, 30.4, 1458 }, note = "达拉然学徒在(银松森林 50,60)，13-14 级且无护法怪，沿路就能打；琥珀磨坊一带(银松森林 55,65)刷新快、护法会召唤小蛇，贴外围打。" },
    [1962] = { n = "Spellfire Robes", cn = "魔焰长袍", l = 15, r = 15, f = "H", s = { { 11049, "雷安诺·戴维斯", "幽暗城", 70.2, 30.2, 1458 } }, e = { 4576, "乔瑟夫·格里高利", "幽暗城", 70.6, 30.4, 1458 }, items = { 7510 } },
    [1963] = { n = "The Shattered Hand", cn = "碎手氏族", l = 13, r = 10, f = "H", races = { 2, 8 }, s = { { 6446, "瑟祖克", "奥格瑞玛", 42.8, 53.4, 1454 } }, e = { 6446, "瑟祖克", "奥格瑞玛", 42.8, 53.4, 1454 }, note = "塔赞在海盗营地右侧的山坡上下巡逻，12 级以下可在坡底杀只怪等他下来再动手；后续目标在奥格瑞玛旅店，不用跑回棘齿城。" },
    [1978] = { n = "The Deathstalkers", cn = "亡灵哨兵", l = 13, r = 10, f = "H", races = { 5 }, s = { { 6467, "米奈特·卡加德", "幽暗城", 83.2, 69, 1458 } }, e = { 2425, "瓦里玛萨斯", "幽暗城", 56.2, 92.6, 1458 }, items = { 7298 }, note = "交给瓦里玛萨斯——幽暗城王座厅正中的大恶魔(幽暗城 57,91)，从精英卫兵中间直接走进去交任务即可。" },
    [1998] = { n = "Fenwick Thatros", cn = "芬维克·萨托斯", l = 16, r = 16, f = "H", races = { 5 }, s = { { 6467, "米奈特·卡加德", "幽暗城", 83.2, 69, 1458 } }, e = { 6467, "米奈特·卡加德", "幽暗城", 83.2, 69, 1458 }, note = "盗贼专属目标：在码头上巡逻的 16 级非精英(提瑞斯法林地 60,34)，很好解决。" },
    [1999] = { n = "Tools of the Trade", cn = "交易工具", l = 20, r = 16, f = "H", races = { 5 }, s = { { 6467, "米奈特·卡加德", "幽暗城", 83.2, 69, 1458 } }, e = { 6467, "米奈特·卡加德", "幽暗城", 83.2, 69, 1458 }, note = "箱子在(银松森林 63,65)那栋楼的二楼，楼上三只 19 级法师怪；一级开锁也试两次就能开，不必先做棘齿城的开锁任务。" },
    [2205] = { n = "Seek out SI: 7", cn = "军情七处", l = 10, r = 10, f = "A", s = { { 917, "科瑞恩·塞尔留斯", "艾尔文森林", 43.8, 65.8, 1429 } }, e = { 332, "马迪亚斯·肖尔大师", "暴风城", 75.8, 59.8, 1453 }, note = "马迪亚斯在暴风城旧城区军情七处二楼(暴风城 76,60)。" },
    [2206] = { n = "Snatch and Grab", cn = "连偷带抢", l = 10, r = 10, f = "A", s = { { 332, "马迪亚斯·肖尔大师", "暴风城", 75.8, 59.8, 1453 } }, e = { 332, "马迪亚斯·肖尔大师", "暴风城", 75.8, 59.8, 1453 }, items = { 7298 }, note = "这是纯偷窃任务，潜行到目标背后偷窃即可，杀怪没用；目标建筑在杰罗德码头(荆棘谷 47,87)，外围零星怪加一组巡逻，潜行进场。" },
    [2218] = { n = "Road to Salvation", cn = "救赎之路", l = 10, r = 10, f = "A", s = { { 1234, "霍格拉尔·巴坎", "丹莫罗", 47.6, 52.6, 1426 } }, e = { 5165, "霍夫丹·黑须", "铁炉堡", 51.6, 14.8, 1455 }, note = "目标在达纳苏斯幽暗洞穴最北端(达纳苏斯 51,14)。" },
    [2238] = { n = "Simple Subterfugin'", cn = "国王的财宝", l = 10, r = 10, f = "A", s = { { 5165, "霍夫丹·黑须", "铁炉堡", 51.6, 14.8, 1455 } }, e = { 6886, "奥宁·雨锤", "丹莫罗", 25.2, 44.4, 1426 }, note = "目标隐身站在侏儒工程平台顶上(丹莫罗 25,44)；千万别走进诺莫瑞根，里面 25+ 级的怪会要命。" },
    [2239] = { n = "Onin's Report", cn = "奥宁的报告", l = 10, r = 10, f = "A", s = { { 6886, "奥宁·雨锤", "丹莫罗", 25.2, 44.4, 1426 } }, e = { 5165, "霍夫丹·黑须", "铁炉堡", 51.6, 14.8, 1455 }, items = { 7298 } },
    [2241] = { n = "The Apple Falls", cn = "詹诺克的花", l = 10, r = 10, f = "A", s = { { 3599, "詹诺克·柔歌", "泰达希尔", 56.2, 60, 1438 } }, e = { 4163, "塞尤娜", "达纳苏斯", 36.8, 21.8, 1457 }, note = "花在达纳苏斯塞纳里奥区的小树上(达纳苏斯 32,16)：过大桥后左转，骑术教官旁那棵有分叉的小树上采集。" },
    [2242] = { n = "Destiny Calls", cn = "命运的召唤", l = 10, r = 10, f = "A", s = { { 4163, "塞尤娜", "达纳苏斯", 36.8, 21.8, 1457 } }, e = { 4163, "塞尤娜", "达纳苏斯", 36.8, 21.8, 1457 }, items = { 7298 }, note = "塞希尔是 12 级萨特(泰达希尔 37,22)：先知林地以北的树墙有个 V 形缺口，沿树枝走出去就能看到；潜行接近先闷棍再偷窃，稳稳完成。" },
    [2259] = { n = "Erion Shadewhisper", cn = "艾瑞安·影语", l = 16, r = 16, f = "A", s = { { 3599, "詹诺克·柔歌", "泰达希尔", 56.2, 60, 1438 } }, e = { 4214, "艾瑞安·影语", "达纳苏斯", 34.6, 25.6, 1457 } },
