    [2298] = { n = "Kingly Shakedown", cn = "国王的搜查", l = 16, r = 16, f = "A", s = { { 5165, "霍夫丹·黑须", "铁炉堡", 51.6, 14.8, 1455 } }, e = { 6946, "“剃刀”雷吉克", "暴风城", 75.8, 60.2, 1453 }, note = "不需要前置任务；目标 NPC 就在铁炉堡盗贼训练屋的底层。" },
