    [2300] = { n = "SI:7", cn = "军情七处", l = 16, r = 16, f = "A", s = { { 917, "科瑞恩·塞尔留斯", "艾尔文森林", 43.8, 65.8, 1429 } }, e = { 6946, "“剃刀”雷吉克", "暴风城", 75.8, 60.2, 1453 } },
    [2359] = { n = "Klaven's Tower", cn = "克拉文之塔", l = 24, r = 20, f = "A", s = { { 7024, "密探吉尔妮", "西部荒野", 68.4, 70, 1436 } }, e = { 332, "马迪亚斯·肖尔大师", "暴风城", 75.8, 59.8, 1453 }, items = { 18160 }, spells = { 2842 }, note = "钥匙要从塔周围巡逻的畸形迪菲亚守卫身上偷，常落单很好下手；塔顶宝箱必须开锁 70 以上才能开，偷来的钥匙不管用；开箱会中赞吉尔之触，用后续任务或德鲁伊/萨满/急救抗毒剂解。" },
    [2360] = { n = "Mathias and the Defias", cn = "马迪亚斯和迪菲亚潜行者", l = 20, r = 20, f = "A", s = { { 332, "马迪亚斯·肖尔大师", "暴风城", 75.8, 59.8, 1453 } }, e = { 7024, "密探吉尔妮", "西部荒野", 68.4, 70, 1436 }, note = "先潜行到塔北第三棵大树西侧找克宁(西部荒野 68,70)，头顶黄问号；畸形守卫多试几次即可偷到，被追用疾跑甩开；20 级可全程单做。" },
    [2378] = { n = "Find the Shattered Hand", cn = "寻找碎手氏族", l = 16, r = 16, f = "H", races = { 2, 5, 8 }, s = { { 6467, "米奈特·卡加德", "幽暗城", 83.2, 69, 1458 } }, e = { 3401, "申苏尔", "奥格瑞玛", 43, 53.4, 1454 }, note = "辛图尔在(奥格瑞玛 43,54)。" },
