    [6101] = { n = "Taming the Beast", cn = "驯服野兽", l = 10, r = 10, f = "A", races = { 4 }, s = { { 3601, "达扎拉", "泰达希尔", 56.6, 59.6, 1438 } }, e = { 3601, "达扎拉", "泰达希尔", 56.6, 59.6, 1438 }, note = "夜刃豹潜伏者在(泰达希尔 56,75)：多兰纳尔正南穿湖而过就是；别抓成营地附近普通的夜刃豹。" },
    [6102] = { n = "Taming the Beast", cn = "驯服野兽", l = 10, r = 10, f = "A", races = { 4 }, s = { { 3601, "达扎拉", "泰达希尔", 56.6, 59.6, 1438 } }, e = { 3601, "达扎拉", "泰达希尔", 56.6, 59.6, 1438 }, spells = { 1515 }, note = "猫头鹰在达纳苏斯城外一带游荡(泰达希尔 44,50 附近)。" },
    [6103] = { n = "Training the Beast", cn = "训练野兽", l = 10, r = 10, f = "A", races = { 4 }, s = { { 3601, "达扎拉", "泰达希尔", 56.6, 59.6, 1438 } }, e = { 4146, "祖卡斯特", "达纳苏斯", 40.2, 8.8, 1457 }, spells = { 5149 } },
    [6121] = { n = "Lessons Anew", cn = "新的课程", l = 14, r = 14, f = "A", races = { 4, 95 }, s = { { 4217, "玛斯雷·驭熊者", "达纳苏斯", 35.2, 8, 1457 }, { 270459, "阿尔菲娜·夜凝", "奥特兰克山脉", 11.8, 56.6, 1416 } }, e = { 11802, "德迪利特·星焰", "月光林地", 56.2, 30.4, 1450 }, note = "从达纳苏斯的玛斯雷·驭熊者处接起；整条链最终奖励解毒术，经验也不少，值得做完。" },
    [6122] = { n = "The Principal Source", cn = "毒水之源", l = 14, r = 14, f = "A", races = { 4, 95 }, s = { { 11802, "德迪利特·星焰", "月光林地", 56.2, 30.4, 1450 } }, e = { 3702, "奥兰达利亚·夜歌", "黑海岸", 37.6, 40.6, 1439 }, note = "注意要在黑海岸取水而非月光林地：装水点(黑海岸 54,33)在洞口瀑布顶上，别在河里灌；取完水小心身后洞里方向的 15 级娜迦。" },
    [6123] = { n = "Gathering the Cure", cn = "收集解药", l = 14, r = 14, f = "A", races = { 4, 95 }, s = { { 3702, "奥兰达利亚·夜歌", "黑海岸", 37.6, 40.6, 1439 } }, e = { 3702, "奥兰达利亚·夜歌", "黑海岸", 37.6, 40.6, 1439 }, note = "月菌在枭兽洞穴里(黑海岸 43,45)多处都有；地根草直接找草药商人买，不用自己采。" },
    [6124] = { n = "Curing the Sick", cn = "消除疾病", l = 14, r = 14, f = "A", races = { 4, 95 }, s = { { 3702, "奥兰达利亚·夜歌", "黑海岸", 37.6, 40.6, 1439 } }, e = { 11802, "德迪利特·星焰", "月光林地", 56.2, 30.4, 1450 }, items = { 15866 }, note = "找被绿色病云包围的鹿，选中后使用药膏即完成；病鹿散布在湖边与林间，数量足够。" },
    [6125] = { n = "Power over Poison", cn = "解毒之术", l = 14, r = 14, f = "A", races = { 4, 95 }, s = { { 11802, "德迪利特·星焰", "月光林地", 56.2, 30.4, 1450 } }, e = { 4217, "玛斯雷·驭熊者", "达纳苏斯", 35.2, 8, 1457 }, spells = { 8946 }, note = "交回达纳苏斯塞纳里奥区中央建筑上层(达纳苏斯 35,8)，完成即学会解毒术。" },
    [6126] = { n = "Lessons Anew", cn = "新的课程", l = 14, r = 14, f = "H", races = { 6, 96 }, s = { { 3033, "图拉克·符文图腾", "雷霆崖", 76.4, 27.6, 1456 }, { 262560, "哈娜·轻蹄", "莫高雷", 33.4, 22, 1412 } }, e = { 11802, "德迪利特·星焰", "月光林地", 56.2, 30.4, 1450 }, note = "从雷霆崖职业训练师接起，用传送月光林地过去；回程找飞行管理员(月光林地 44,45)直飞，炉石记得留在十字路口附近。" },
    [6127] = { n = "The Principal Source", cn = "毒水之源", l = 14, r = 14, f = "H", races = { 6, 96 }, s = { { 11802, "德迪利特·星焰", "月光林地", 56.2, 30.4, 1450 } }, e = { 3448, "图加·符文图腾", "贫瘠之地", 52.2, 31.8, 1413 }, note = "恐怖之峰在十字路口西北(贫瘠之地 47,17)：山顶洞穴上方有个小水塘，清完四周怪再灌瓶；灌完会从地里爬出几只 13 级怪，杀掉即安。" },
    [6128] = { n = "Gathering the Cure", cn = "收集解药", l = 14, r = 14, f = "H", races = { 6, 96 }, s = { { 3448, "图加·符文图腾", "贫瘠之地", 52.2, 31.8, 1413 } }, e = { 3448, "图加·符文图腾", "贫瘠之地", 52.2, 31.8, 1413 }, note = "走失的贫瘠之地科多兽在淤泥沼泽(贫瘠之地 55,11)，掉率 100%；地根草不用学采药——十字路口的药剂商有售（3 根 80 铜）。" },
    [6129] = { n = "Curing the Sick", cn = "消除疾病", l = 14, r = 14, f = "H", races = { 6, 96 }, s = { { 3448, "图加·符文图腾", "贫瘠之地", 52.2, 31.8, 1413 } }, e = { 11802, "德迪利特·星焰", "月光林地", 56.2, 30.4, 1450 }, items = { 15866 }, note = "用缠绕根须定住病畜再涂药膏效率更高；注意在它被根须磨死之前涂，死了就不计入。" },
    [6130] = { n = "Power over Poison", cn = "解毒之术", l = 14, r = 14, f = "H", races = { 6, 96 }, s = { { 11802, "德迪利特·星焰", "月光林地", 56.2, 30.4, 1450 } }, e = { 3033, "图拉克·符文图腾", "雷霆崖", 76.4, 27.6, 1456 }, spells = { 8946 }, note = "交回雷霆崖长者高地的图拉克·图腾(雷霆崖 76,27)，完成即学会解毒术；纯练级也可跳过，26 级再学驱毒术。" },
    [6681] = { n = "The Manor, Ravenholdt", cn = "拉文霍德庄园", l = 24, r = 24, e = { 6707, "法拉德", "奥特兰克山脉", 84.4, 80.2, 1416 }, note = "需 24 级且学会侦测陷阱；庄园在塔伦米尔东南的山地上，上山路在敦霍尔德要塞北方高台之后(希尔斯布莱德丘陵 75,24)；开箱会刷出 33 级精英，提前备好脱身手段。" },
    [6701] = { n = "Syndicate Emblems", cn = "辛迪加徽章", l = 60, r = 24, s = { { 6766, "拉文霍德卫兵", "奥特兰克山脉", 84.4, 79.4, 1416 }, { 6766, "拉文霍德卫兵", "希尔斯布莱德丘陵", 77.6, 20, 1424 } }, e = { 6766, "拉文霍德卫兵", "奥特兰克山脉", 84.4, 79.4, 1416 } },
    [6721] = { n = "The Hunter's Path", cn = "猎人之道", l = 10, r = 10, f = "A", races = { 4 }, s = { { 5116, "奥尔明·燃须", "铁炉堡", 70.6, 83.8, 1455 } }, e = { 3601, "达扎拉", "泰达希尔", 56.6, 59.6, 1438 } },
    [6722] = { n = "The Hunter's Path", cn = "猎人之道", l = 10, r = 10, f = "A", races = { 4 }, s = { { 1231, "格瑞夫", "丹莫罗", 45.8, 53, 1426 } }, e = { 3601, "达扎拉", "泰达希尔", 56.6, 59.6, 1438 } },
    [7463] = { n = "Arcane Refreshment", cn = "久违的法师", l = 60, r = 60, s = { { 14368, "博学者莱德罗斯", "厄运之槌", 0, 0 } }, e = { 14368, "博学者莱德罗斯", "厄运之槌", 0, 0 }, spells = { 10140 }, note = "从厄运之槌图书馆接取（西、北两区均可进入），60 级法师的必做链。" },
    [7562] = { n = "Mor'zul Bloodbringer", cn = "莫苏尔·召血者", l = 58, r = 60, s = { { 5520, "斯巴克尔", "暴风城", 25.8, 77.6, 1453 }, { 5753, "马尔萨·斯坦恩", "幽暗城", 85.8, 15.8, 1458 }, { 5815, "库古尔", "奥格瑞玛", 47.6, 46.8, 1454 }, { 6382, "寻尸者祖贝尔", "铁炉堡", 53, 6.2, 1455 } }, e = { 14436, "莫苏尔·召血者", "燃烧平原", 12.6, 31.6, 1428 }, note = "恐惧战马链的起点：莫祖尔·召血者在燃烧平原(燃烧平原 12,31)，需 60 级；全程预算至少 150 金，提前备好。" },
    [7563] = { n = "Rage of Blood", cn = "血之狂暴", l = 58, r = 60, s = { { 14436, "莫苏尔·召血者", "燃烧平原", 12.6, 31.6, 1428 } }, e = { 14436, "莫苏尔·召血者", "燃烧平原", 12.6, 31.6, 1428 }, note = "血样由费伍德森林隐匿林一带(费伍德森林 65,21)的狼形怪掉落，掉率 20-48% 不等，一小时左右能刷完；可与「荒野守护者」链同怪一起做。" },
    [7564] = { n = "Wildeyes", cn = "戈瑟奇·邪眼", l = 58, r = 60, s = { { 14436, "莫苏尔·召血者", "燃烧平原", 12.6, 31.6, 1428 } }, e = { 14437, "戈瑟奇·邪眼", "燃烧平原", 12.4, 31.6, 1428 }, note = "后续分成多件道具的小任务，最终要进通灵学院完成召唤仪式，别在野外等收尾。" },
    [7581] = { n = "The Prison's Bindings", cn = "监牢之链", l = 60, r = 60, s = { { 14463, "衰老的戴奥", "诅咒之地", 34, 50.2, 1419 } }, e = { 14463, "衰老的戴奥", "诅咒之地", 34, 50.2, 1419 }, note = "从菲拉斯的厄运之槌后门进入；四人组打法：虚空行者缠住贼、放逐另一只，逐个上 DOT 慢慢磨。" },
    [7582] = { n = "The Prison's Casing", cn = "监牢之壁", l = 60, r = 60, s = { { 14463, "衰老的戴奥", "诅咒之地", 34, 50.2, 1419 } }, e = { 14463, "衰老的戴奥", "诅咒之地", 34, 50.2, 1419 }, note = "怪可恐惧可放逐：末日诅咒+先 30 秒再 20 秒的放逐轮着来；掉率偏低，要有耐心。" },
    [7583] = { n = "Suppression", cn = "压制", l = 60, r = 60, s = { { 14463, "衰老的戴奥", "诅咒之地", 34, 50.2, 1419 } }, e = { 14463, "衰老的戴奥", "诅咒之地", 34, 50.2, 1419 }, items = { 18602 }, spells = { 18540 }, note = "末日守卫队长在任务点以南(诅咒之地 34,63)，被一圈恶爪精英围着但彼此间距大，可逐个引开再单挑队长。" },
    [7601] = { n = "What Niby Commands", cn = "尼比的助手", l = 50, r = 50, s = { { 14469, "万能的尼比", "费伍德森林", 41.4, 44.8, 1448 } }, e = { 14470, "伊普斯", "费伍德森林", 41.4, 44.8, 1448 }, note = "英普西在费伍德森林(费伍德森林 41,45)；任务 50 级可接，48 级就能拿。" },
    [7602] = { n = "Flawless Fel Essence", cn = "无瑕的恶魔精华", l = 55, r = 50, s = { { 14470, "伊普斯", "费伍德森林", 41.4, 44.8, 1448 } }, e = { 14470, "伊普斯", "费伍德森林", 41.4, 44.8, 1448 }, note = "三块精华：艾萨拉的雷加什营地(艾萨拉 51,19)任意怪都掉；费伍德森林贾德纳尔地下(费伍德森林 35,58)的军团士兵掉率很低；诅咒之地那块注意杀的是恶魔卫士，不是末日守卫。" },
    [7603] = { n = "Kroshius' Infernal Core", cn = "克罗苏斯的恶魔之核", l = 55, r = 50, s = { { 14470, "伊普斯", "费伍德森林", 41.4, 44.8, 1448 } }, e = { 14469, "万能的尼比", "费伍德森林", 41.4, 44.8, 1448 }, items = { 18762 }, spells = { 1122 }, note = "克罗修斯的遗骸在山坡上(燃烧平原 45,35)，就在陨坑正北的高地上，很好找。" },
    [7621] = { n = "A Warning", cn = "警示", l = 60, r = 60, s = { { 14494, "艾瑞斯·哈文法", "东瘟疫之地", 20.8, 18.4, 1423 } }, e = { 14494, "艾瑞斯·哈文法", "东瘟疫之地", 20.8, 18.4, 1423 }, note = "牧师专属；必须持有「神圣之眼」才能看到目标 NPC，否则白跑。" },
    [7622] = { n = "The Balance of Light and Shadow", cn = "光与影的平衡", l = 60, r = 60, s = { { 14494, "艾瑞斯·哈文法", "东瘟疫之地", 20.8, 18.4, 1423 } }, e = { 14494, "艾瑞斯·哈文法", "东瘟疫之地", 20.8, 18.4, 1423 }, items = { 18659 }, note = "记得打开 NPC 血条（Shift+V）盯着农民血量；多名牧师可分工接力加血，难度骤降。" },
    [7623] = { n = "Lord Banehollow", cn = "魔王贝恩霍勒", l = 58, r = 60, s = { { 14437, "戈瑟奇·邪眼", "燃烧平原", 12.4, 31.6, 1428 } }, e = { 9516, "魔王贝恩霍勒", "费伍德森林", 36, 44.6, 1448 }, note = "先在贾德纳尔喝下暗影药剂再前进（沿途怪全绿不会动手）；目标洞穴(费伍德森林 35,59)是第二个洞——过了第一个洞继续走，见到「暗影巢穴」才算到。" },
    [7624] = { n = "Ulathek the Traitor", cn = "背叛者乌拉泰克", l = 58, r = 60, s = { { 9516, "魔王贝恩霍勒", "费伍德森林", 36, 44.6, 1448 } }, e = { 9516, "魔王贝恩霍勒", "费伍德森林", 36, 44.6, 1448 }, note = "乌拉泰克在洞穴深处(费伍德森林 41,48)：从贝恩霍勒处往回朝入口方向走，上坡后右侧岔路走到尽头即是。" },
    [7625] = { n = "Xorothian Stardust", cn = "克索诺斯星尘", l = 60, r = 60, s = { { 9516, "魔王贝恩霍勒", "费伍德森林", 36, 44.6, 1448 } }, e = { 14437, "戈瑟奇·邪眼", "燃烧平原", 12.4, 31.6, 1428 }, note = "这步简单——直接花 150 金向贝恩霍勒购买星尘即可。" },
    [7626] = { n = "Bell of Dethmoora", cn = "达斯莫拉之铃", l = 60, r = 60, s = { { 14436, "莫苏尔·召血者", "燃烧平原", 12.6, 31.6, 1428 } }, e = { 14437, "戈瑟奇·邪眼", "燃烧平原", 12.4, 31.6, 1428 }, note = "需要 2 瓶强效暗影能量药剂（每瓶 3 个幽灵蘑菇，辛特兰的斯库尔岩石区产出多）与 1 根奥金锭。" },
    [7627] = { n = "Wheel of the Black March", cn = "黑暗战车之轮", l = 60, r = 60, s = { { 14436, "莫苏尔·召血者", "燃烧平原", 12.6, 31.6, 1428 } }, e = { 14437, "戈瑟奇·邪眼", "燃烧平原", 12.4, 31.6, 1428 }, note = "暗铁矿石直接拍卖行买，通常不贵，25 块左右足够。" },
    [7628] = { n = "Doomsday Candle", cn = "末日蜡烛", l = 60, r = 60, s = { { 14436, "莫苏尔·召血者", "燃烧平原", 12.6, 31.6, 1428 } }, e = { 14437, "戈瑟奇·邪眼", "燃烧平原", 12.4, 31.6, 1428 }, note = "道具直接购买即可；记得提前备好奥金锭——下一步只需 1 根，别备错数量。" },
    [7629] = { n = "Imp Delivery", cn = "瓶中的小鬼", l = 60, r = 60, s = { { 14437, "戈瑟奇·邪眼", "燃烧平原", 12.4, 31.6, 1428 } }, e = { 14437, "戈瑟奇·邪眼", "燃烧平原", 12.4, 31.6, 1428 }, note = "到通灵学院的炼金实验室激活小鬼（就在雷斯·霜语者所在的房间）；完成后小鬼连罐子一起跟你走，任务纸在罐里，不用翻背包。" },
    [7630] = { n = "Arcanite", cn = "奥金锭", l = 60, r = 60, s = { { 14437, "戈瑟奇·邪眼", "燃烧平原", 12.4, 31.6, 1428 } }, e = { 14437, "戈瑟奇·邪眼", "燃烧平原", 12.4, 31.6, 1428 } },
    [7631] = { n = "Dreadsteed of Xoroth", cn = "克索诺斯恐惧战马", l = 60, r = 60, s = { { 14436, "莫苏尔·召血者", "燃烧平原", 12.6, 31.6, 1428 } }, e = { 14504, "恐惧战马的灵魂", "", 0, 0 }, spells = { 23161 }, note = "做完整条链骑术直接从 75 提到 150，比直接购买史诗坐骑省下大几百金，非常划算。" },
    [7632] = { n = "The Ancient Leaf", cn = "远古石叶", l = 60, r = 60, e = { 14524, "古树瓦特鲁斯", "费伍德森林", 48.8, 24.2, 1448 }, note = "远古石化之叶出自熔火之心：击败管理者埃克索图斯后开启火焰领主的箱囊获得；拿到叶子才是猎人史诗弓链的真正开始。" },
    [7633] = { n = "An Introduction", cn = "介绍", l = 60, r = 60, s = { { 14524, "古树瓦特鲁斯", "费伍德森林", 48.8, 24.2, 1448 } }, e = { 14524, "古树瓦特鲁斯", "费伍德森林", 48.8, 24.2, 1448 } },
    [7634] = { n = "Ancient Sinew Wrapped Lamina", cn = "龙筋箭袋", l = 60, r = 60, s = { { 14526, "古树哈斯塔特", "费伍德森林", 48.2, 24.2, 1448 } }, e = { 14526, "古树哈斯塔特", "费伍德森林", 48.2, 24.2, 1448 }, items = { 18714 }, note = "龙筋由艾索雷苟斯或冬泉谷玛兹索里尔的钴蓝鳞龙掉落；箭袋给远程攻速 +15%，是当前版本最强箭袋。" },
    [7635] = { n = "A Proper String", cn = "合适的弓弦", l = 60, r = 60, s = { { 14525, "古树斯托玛", "费伍德森林", 48.6, 23.2, 1448 } }, e = { 14525, "古树斯托玛", "费伍德森林", 48.6, 23.2, 1448 }, items = { 18724 }, note = "龙筋绳索由奥妮克希亚掉落（约 20%），没有任务也能拾取；团里可以提前打招呼留给你。" },
    [7636] = { n = "Stave of the Ancients", cn = "古树的手杖", l = 60, r = 60, s = { { 14524, "古树瓦特鲁斯", "费伍德森林", 48.8, 24.2, 1448 } }, e = { 14524, "古树瓦特鲁斯", "费伍德森林", 48.8, 24.2, 1448 }, items = { 18707 }, note = "四场恶魔战必须完全单人完成——宠物、饰品召唤物、蛇陷阱统统不能用（蛇陷阱会让恶魔逃跑），任何额外目标进仇恨表即告失败。" },
