    [8151] = { n = "The Hunter's Charm", cn = "猎人的护符", l = 52, r = 50, s = { { 3039, "浩特·雷角", "雷霆崖", 57.4, 89.2, 1456 }, { 3352, "奥玛克", "奥格瑞玛", 66.2, 18.2, 1454 }, { 4205, "多利安", "达纳苏斯", 42.2, 7.6, 1457 }, { 5116, "奥尔明·燃须", "铁炉堡", 70.6, 83.8, 1455 }, { 5516, "奥菲尔·铁须", "暴风城", 62, 15, 1453 } }, e = { 8405, "奥汀克", "艾萨拉", 42.4, 42.6, 1447 }, note = "目标 NPC 在废墟外围的高地上(艾萨拉 42,43)：沿周围山地绕行，别下到废墟里面找；部落版从奥格瑞玛荣誉谷的猎人 NPC 处接。" },
    [8153] = { n = "Courser Antlers", cn = "苔蹄快步者的鹿角", l = 52, r = 50, s = { { 8405, "奥汀克", "艾萨拉", 42.4, 42.6, 1447 } }, e = { 8405, "奥汀克", "艾萨拉", 42.4, 42.6, 1447 }, note = "苔蹄快鹿在艾萨拉南北两区游荡，沿(艾萨拉 35,62)到(艾萨拉 42,72)一线往返刷效率高；掉率极低，要有耐心。" },
    [8231] = { n = "Wavethrashing", cn = "碎浪多头怪", l = 52, r = 50, s = { { 8405, "奥汀克", "艾萨拉", 42.4, 42.6, 1447 } }, e = { 8405, "奥汀克", "艾萨拉", 42.4, 42.6, 1447 }, note = "碎浪鱼在艾达拉之塔周边海域(艾萨拉 86,25)密集；附近有精英鲨鱼游荡，50 级出头单独来要贴着岸边小心走。" },
    [8232] = { n = "The Green Drake", cn = "神庙中的绿龙", l = 52, r = 50, s = { { 8405, "奥汀克", "艾萨拉", 42.4, 42.6, 1447 } }, e = { 8405, "奥汀克", "艾萨拉", 42.4, 42.6, 1447 }, items = { 20083, 19991, 19992 } },
    [8233] = { n = "A Simple Request", cn = "简单的要求", l = 52, r = 50, s = { { 918, "夜行者奥斯伯", "暴风城", 74.4, 52.8, 1453 }, { 3328, "奥莫克", "奥格瑞玛", 44, 54.4, 1454 }, { 4163, "塞尤娜", "达纳苏斯", 36.8, 21.8, 1457 }, { 4583, "迈尔斯·迪克斯特", "幽暗城", 85, 71.2, 1458 }, { 5165, "霍夫丹·黑须", "铁炉堡", 51.6, 14.8, 1455 } }, e = { 6768, "乔拉齐·拉文霍德公爵", "奥特兰克山脉", 86, 79, 1416 }, note = "庄园入口在(希尔斯布莱德丘陵 75,23)；部落版从幽暗城盗贼训练师迈尔斯·德克斯特(幽暗城 85,72)处接。" },
    [8234] = { n = "Sealed Azure Bag", cn = "密封的蓝袋子", l = 52, r = 50, s = { { 6768, "乔拉齐·拉文霍德公爵", "奥特兰克山脉", 86, 79, 1416 } }, e = { 8379, "大法师克希雷姆", "艾萨拉", 29.2, 40.2, 1447 }, note = "蓝袋子可从萨满祭司身上偷到：先闷棍再偷，约 8-10 次内能出；与木喉要塞声望无关，全程潜行偷过去即可。" },
    [8235] = { n = "Encoded Fragments", cn = "密文碎片", l = 52, r = 50, s = { { 8379, "大法师克希雷姆", "艾萨拉", 29.2, 40.2, 1447 } }, e = { 8379, "大法师克希雷姆", "艾萨拉", 29.2, 40.2, 1447 }, note = "先偷窃再杀怪；全艾萨拉的野兽都算数，雷首角鹰兽尤其好打，还会顺带掉后续要的长羽毛。" },
