    [8249] = { n = "Junkboxes Needed", cn = "垃圾箱", l = 60, r = 50, s = { { 6707, "法拉德", "奥特兰克山脉", 84.4, 80.2, 1416 } }, e = { 6707, "法拉德", "奥特兰克山脉", 84.4, 80.2, 1416 }, items = { 20086 }, note = "开完箱子把不值钱的战利品留在箱里再上交，既拿钱又保住任务箱；每次最多交 5 个，是拉文霍德声望的主要来源。" },
    [8250] = { n = "Magecraft", cn = "法师的会见", l = 52, r = 50, s = { { 331, "玛吉诺·仲马", "暴风城", 38, 81.6, 1453 }, { 3047, "大法师山姆", "雷霆崖", 22.6, 14.8, 1456 }, { 4567, "皮尔斯·沙克尔顿", "幽暗城", 85.4, 13.8, 1458 }, { 7311, "尤塞尔奈", "奥格瑞玛", 39, 86, 1454 }, { 7312, "丁克", "铁炉堡", 26.8, 8.4, 1455 } }, e = { 8395, "萨纳斯", "艾萨拉", 28, 50, 1447 }, note = "与萨纳斯对话会把你传送上悬崖，沿小路骑到塔顶找塞勒姆。" },
    [8251] = { n = "Magic Dust", cn = "魔法的尘埃", l = 52, r = 50, s = { { 8379, "大法师克希雷姆", "艾萨拉", 29.2, 40.2, 1447 } }, e = { 8379, "大法师克希雷姆", "艾萨拉", 29.2, 40.2, 1447 }, note = "血精灵营地在小山上(艾萨拉 55,26)；尘埃掉率一般，杀十几只左右能凑齐。" },
    [8252] = { n = "The Siren's Coral", cn = "纳迦的珊瑚", l = 52, r = 50, s = { { 8379, "大法师克希雷姆", "艾萨拉", 29.2, 40.2, 1447 } }, e = { 8379, "大法师克希雷姆", "艾萨拉", 29.2, 40.2, 1447 }, note = "海妖塞壬在(艾萨拉 48,50)一带密集且多落单，掉率约三分之一，比别处省力。" },
