    [8254] = { n = "Cenarion Aid", cn = "塞纳里奥议会的求助", l = 52, r = 50, s = { { 5489, "乔舒修士", "暴风城", 38.8, 26.8, 1453 }, { 6018, "乌尔库", "奥格瑞玛", 35.6, 87.6, 1454 }, { 11406, "高阶牧师洛汉", "铁炉堡", 25, 8.4, 1455 } }, e = { 8405, "奥汀克", "艾萨拉", 42.4, 42.6, 1447 }, note = "提前备一瓶亡灵腐液，第三步要用；目标 NPC 在(艾萨拉 42,42)；部落版找奥格瑞玛的牧师训练师接同款。" },
    [8255] = { n = "Of Coursers We Know", cn = "苔蹄快步者", l = 52, r = 50, s = { { 8405, "奥汀克", "艾萨拉", 42.4, 42.6, 1447 } }, e = { 8405, "奥汀克", "艾萨拉", 42.4, 42.6, 1447 }, note = "苔蹄鹿在山区南麓成群(艾萨拉 54,25 附近)；与角鹰兽共用刷新点——鹿少时杀几只角鹰兽能腾出刷新位。" },
    [8256] = { n = "The Ichor of Undeath", cn = "亡灵的腐液", l = 52, r = 50, s = { { 8405, "奥汀克", "艾萨拉", 42.4, 42.6, 1447 } }, e = { 8405, "奥汀克", "艾萨拉", 42.4, 42.6, 1447 }, note = "亡灵腐液建议提前在西瘟疫之地刷怪或拍卖行买好；艾萨拉的上层精灵巫妖也掉，但怪稀且掉率低。" },
    [8257] = { n = "Blood of Morphaz", cn = "摩弗拉斯之血", l = 52, r = 50, s = { { 8405, "奥汀克", "艾萨拉", 42.4, 42.6, 1447 } }, e = { 10922, "格雷塔·苔蹄", "费伍德森林", 51.2, 82.2, 1448 }, items = { 19990, 20082, 20006 } },
