    [8410] = { n = "Elemental Mastery", cn = "元素掌握", l = 52, r = 50, f = "H", races = { 2, 6, 8, 96 }, s = { { 3032, "博拉姆·逐星", "雷霆崖", 22.2, 19, 1456 }, { 13417, "萨格尼", "奥格瑞玛", 38.6, 36.2, 1454 } }, e = { 6176, "捕风者巴斯拉", "奥特兰克山脉", 80.4, 66.8, 1416 }, note = "三种元素精华在阿拉希的各处绑缚法阵刷，掉率很好；每种只需 1 个，不用囤货。" },
