    [8413] = { n = "Da Voodoo", cn = "巫毒羽毛", l = 52, r = 50, f = "H", s = { { 6176, "捕风者巴斯拉", "奥特兰克山脉", 80.4, 66.8, 1416 } }, e = { 6176, "捕风者巴斯拉", "奥特兰克山脉", 80.4, 66.8, 1416 }, items = { 20369, 20503, 20556 }, note = "饰品会占用水图腾槽位，与潮汐图腾互斥，开怪前想好带哪个；后续要进沉没的神庙连杀六座小 BOSS。" },
    [8414] = { n = "Dispelling Evil", cn = "驱散邪恶", l = 52, r = 50, f = "A", races = { 1, 3 }, s = { { 10838, "指挥官阿什拉姆·瓦罗菲斯特", "西瘟疫之地", 42.8, 84, 1422 } }, e = { 1854, "高阶牧师赛尔丹尼斯", "西瘟疫之地", 52, 82.8, 1422 }, note = "别只对话——把委任状装进饰品栏才生效；不掉任务品时先检查自己有没有装备它。" },
    [8415] = { n = "Chillwind Point", cn = "冰风岗", l = 52, r = 50, f = "A", races = { 1, 3 }, s = { { 928, "格雷森·沙东布瑞克公爵", "暴风城", 37.2, 33, 1453 }, { 5149, "布兰度尔·铁锤", "铁炉堡", 23.4, 6.2, 1455 } }, e = { 10838, "指挥官阿什拉姆·瓦罗菲斯特", "西瘟疫之地", 42.8, 84, 1422 } },
