    [8417] = { n = "A Troubled Spirit", cn = "困扰的灵魂", l = 52, r = 50, s = { { 3354, "索瑞克", "奥格瑞玛", 80.2, 32.4, 1454 }, { 4593, "克里斯托弗·沃克", "幽暗城", 47.2, 15.2, 1458 }, { 5113, "凯夫·重锤", "铁炉堡", 70, 90.6, 1455 }, { 5479, "武神", "暴风城", 78.8, 45.6, 1453 }, { 7315, "达纳斯·刃歌", "达纳苏斯", 58.6, 35.4, 1457 } }, e = { 7572, "部落英雄的灵魂", "悲伤沼泽", 34.2, 66, 1435 }, note = "50 级起由主城战士训练师发放的引导任务；目标「堕落的勇士」在悲伤沼泽最南端路旁(悲伤沼泽 34,66)。" },
    [8418] = { n = "Forging the Mightstone", cn = "铸造力量之石", l = 52, r = 50, f = "A", races = { 1, 3 }, s = { { 10838, "指挥官阿什拉姆·瓦罗菲斯特", "西瘟疫之地", 42.8, 84, 1422 } }, e = { 10838, "指挥官阿什拉姆·瓦罗菲斯特", "西瘟疫之地", 42.8, 84, 1422 }, items = { 20620, 20504, 20512, 20505 }, note = "圣光力量石唯一且一次性使用，用在哪场战斗想清楚；50 级时饰品约等于 3.7% 暴击。" },
    [8419] = { n = "An Imp's Request", cn = "小鬼的要求", l = 52, r = 50, s = { { 461, "德米赛特·克劳斯", "暴风城", 25.4, 78.2, 1453 }, { 3326, "泽维斯特", "奥格瑞玛", 48.4, 45.6, 1454 }, { 4563, "卡尔·噬灵", "幽暗城", 86, 15.6, 1458 }, { 5172, "布瑞尔索恩", "铁炉堡", 50.2, 6, 1455 } }, e = { 14470, "伊普斯", "费伍德森林", 41.4, 44.8, 1448 }, note = "50 级可接，部落版在幽暗城或奥格瑞玛的恶魔训练师处领；恶魔布可在费伍德森林刷萨特自给，顺路还能接英普西的地狱火任务。" },
    [8420] = { n = "Hot and Itchy", cn = "灼热的疼痛", l = 52, r = 50, s = { { 14470, "伊普斯", "费伍德森林", 41.4, 44.8, 1448 } }, e = { 14470, "伊普斯", "费伍德森林", 41.4, 44.8, 1448 } },
    [8421] = { n = "The Wrong Stuff", cn = "奇怪的材料", l = 52, r = 50, s = { { 14470, "伊普斯", "费伍德森林", 41.4, 44.8, 1448 } }, e = { 14470, "伊普斯", "费伍德森林", 41.4, 44.8, 1448 }, note = "腐烂的木头在铁树区(费伍德森林 47,26)，路过的大树人掉率更高；污染淤泥在湖边(费伍德森林 42,45)刷更快；血毒精华掉率约 80%。" },
    [8422] = { n = "Trolls of a Feather", cn = "巨魔的羽毛", l = 52, r = 50, s = { { 14470, "伊普斯", "费伍德森林", 41.4, 44.8, 1448 } }, e = { 14470, "伊普斯", "费伍德森林", 41.4, 44.8, 1448 }, items = { 20536, 20534, 20530 } },
    [8423] = { n = "Warrior Kinship", cn = "战士的血脉", l = 52, r = 50, s = { { 7572, "部落英雄的灵魂", "悲伤沼泽", 34.2, 66, 1435 } }, e = { 7572, "部落英雄的灵魂", "悲伤沼泽", 34.2, 66, 1435 }, note = "目标兽群在黑暗之门以西(诅咒之地 51,54)一带游荡，53 级战士可单刷；数量不够时等几分钟刷新即可。" },
    [8424] = { n = "War on the Shadowsworn", cn = "魔誓者之战", l = 52, r = 50, s = { { 7572, "部落英雄的灵魂", "悲伤沼泽", 34.2, 66, 1435 } }, e = { 7572, "部落英雄的灵魂", "悲伤沼泽", 34.2, 66, 1435 }, note = "魔誓者集中在守望堡与黑暗之门之间(诅咒之地 64,32)，附近山洞里也有；小心水晶旁的「阿利斯塔贾之仆」是其他任务的怪，动不了水晶就打不动它。" },
    [8425] = { n = "Voodoo Feathers", cn = "巫毒羽毛", l = 52, r = 50, s = { { 7572, "部落英雄的灵魂", "悲伤沼泽", 34.2, 66, 1435 } }, e = { 7572, "部落英雄的灵魂", "悲伤沼泽", 34.2, 66, 1435 }, items = { 20521, 20130, 20517 }, note = "完成即获 15 分钟 +400 攻击强度的增益，可以顺手在诅咒之地刷 15 分钟怪吃经验。" },
    [9051] = { n = "Toxic Test", cn = "毒性测试", l = 52, r = 50, s = { { 9619, "托尔瓦·寻路者", "安戈洛环形山", 71.6, 76, 1449 } }, e = { 9619, "托尔瓦·寻路者", "安戈洛环形山", 71.6, 76, 1449 }, note = "找魔暴龙要有耐心，遇上了先休眠、扎一针就跑，别恋战。" },
    [9052] = { n = "Bloodpetal Poison", cn = "血瓣毒药", l = 52, r = 50, s = { { 9619, "托尔瓦·寻路者", "安戈洛环形山", 71.6, 76, 1449 } }, e = { 9619, "托尔瓦·寻路者", "安戈洛环形山", 71.6, 76, 1449 }, items = { 13446 }, note = "蜂刺由(安戈洛环形山-滑行者疤痕 50,76)的黄蜂掉落，掉率偏低；血盖菇藏在血瓣花苗里——带货的花苗会闪光，只摘发光的；草药师记得关掉「寻找草药」避免干扰。" },
    [9053] = { n = "A Better Ingredient", cn = "更好的材料", l = 52, r = 50, s = { { 9619, "托尔瓦·寻路者", "安戈洛环形山", 71.6, 76, 1449 } }, e = { 9619, "托尔瓦·寻路者", "安戈洛环形山", 71.6, 76, 1449 }, items = { 22274, 22272, 22458 }, note = "六座雕像按钟点顺序点亮：6 点→12 点→8 点→4 点→10 点→2 点，即南、北、西南、东南、西北、东北；点对了雕像会亮绿光。" },
    [9063] = { n = "Torwa Pathfinder", cn = "托尔瓦·寻路者", l = 52, r = 50, s = { { 3033, "图拉克·符文图腾", "雷霆崖", 76.4, 27.6, 1456 }, { 4217, "玛斯雷·驭熊者", "达纳苏斯", 35.2, 8, 1457 }, { 5505, "塞瑞德兰", "暴风城", 21.4, 51.4, 1453 }, { 12042, "洛甘纳尔", "月光林地", 52.4, 40.4, 1450 } }, e = { 9619, "托尔瓦·寻路者", "安戈洛环形山", 71.6, 76, 1449 }, note = "50 级由职业训练师发放：达纳苏斯找玛斯雷·驭熊者（德迪特里昂不给）；注意莫沙切的部落训练师不给这个任务。" },
    [9362] = { n = "Warlord Krellian", cn = "军阀克雷利安", l = 60, r = 60, s = { { 8379, "大法师克希雷姆", "艾萨拉", 29.2, 40.2, 1447 } }, e = { 8379, "大法师克希雷姆", "艾萨拉", 29.2, 40.2, 1447 }, note = "顺路可上神庙上层找稀有精英「牙锋将军」，约 2 小时一刷，60 级打他很轻松；站楼下用目标框输入名字试探即可。" },
    [9364] = { n = "Fragmented Magic", cn = "魔法的碎片", l = 60, r = 60, s = { { 8379, "大法师克希雷姆", "艾萨拉", 29.2, 40.2, 1447 } }, e = { 8379, "大法师克希雷姆", "艾萨拉", 29.2, 40.2, 1447 }, spells = { 28272 }, note = "变形娜迦后立刻凑近：它会分裂出 2-5 个分身，一个魔爆术或冰霜新星全收；注意别用乌龟变形——乌龟形态不会分裂。" },
    [65593] = { n = "Hearts of the Lovers", cn = "爱人的徽记", l = 20, r = 20, f = "H", races = { 2, 5, 8 }, s = { { 5693, "高德瑞克·法杉", "幽暗城", 85, 14.8, 1458 } }, e = { 5675, "凯伦丁·哈加尔", "幽暗城", 85, 25.6, 1458 } },
    [65597] = { n = "The Binding", cn = "束缚", l = 20, r = 20, f = "H", s = { { 5675, "凯伦丁·哈加尔", "幽暗城", 85, 25.6, 1458 } }, e = { 5675, "凯伦丁·哈加尔", "幽暗城", 85, 25.6, 1458 }, items = { 22243 }, spells = { 713 } },
    [65601] = { n = "Love Hurts", cn = "要爱就会受伤害", l = 20, r = 20, f = "H", races = { 2, 5, 8 }, s = { { 5909, "卡祖尔", "奥格瑞玛", 47.2, 46.6, 1454 } }, e = { 3363, "玛加尔", "奥格瑞玛", 63.4, 50, 1454 } },
    [65602] = { n = "What Is Love?", cn = "爱是什么？", l = 20, r = 20, f = "A", races = { 1, 7 }, s = { { 6244, "先知塔卡尔", "贫瘠之地", 49.2, 57, 1413 } }, e = { 6122, "黑暗缚灵者加科因", "暴风城", 25.4, 78.4, 1453 }, note = "目标木雕在屋内二楼，NPC 不让直接拿：先取屋外桌上的未点燃火把；点火需篝火——有烹饪可在原地生火，没有就去佐拉姆海岸塔伦的篝火处(灰谷 15,31)借火，点燃只持续 5 分钟，拿到火别绕路直接回屋外手推车处完成点火。" },
    [65603] = { n = "The Binding", cn = "束缚", l = 20, r = 20, f = "A", races = { 1, 7 }, s = { { 6122, "黑暗缚灵者加科因", "暴风城", 25.4, 78.4, 1453 } }, e = { 6122, "黑暗缚灵者加科因", "暴风城", 25.4, 78.4, 1453 }, items = { 22243 }, spells = { 713 } },
    [65604] = { n = "The Binding", cn = "束缚", l = 20, r = 20, f = "H", races = { 2, 5 }, s = { { 5875, "莫达克·黑拳", "奥格瑞玛", 48.2, 45.6, 1454 } }, e = { 5875, "莫达克·黑拳", "奥格瑞玛", 48.2, 45.6, 1454 }, items = { 22243 }, spells = { 713 }, note = "与魅魔召唤同源：召唤男魅魔是独立法术，不与魅魔共享恶魔技能书，两种都想用的话技能书要各买一份，选好主用方向再投入。" },
    [65610] = { n = "Wish You Were Here", cn = "希望你还在", l = 27, r = 20, f = "H", races = { 2, 5, 8 }, s = { { 3363, "玛加尔", "奥格瑞玛", 63.4, 50, 1454 } }, e = { 5875, "莫达克·黑拳", "奥格瑞玛", 48.2, 45.6, 1454 } },
    [78088] = { n = "A Strange Artifact", cn = "怪异的神器", l = 30, r = 22, f = "A", s = { { 409289, "奇怪的光球", "黑海岸", 56.2, 26.4, 1439 } }, e = { 3663, "净化者德尔格伦", "灰谷", 26.2, 38.6, 1440 } },
    [78089] = { n = "Advice From Stormwind", cn = "暴风城的建议", l = 30, r = 22, f = "A", races = { 1, 3 }, s = { { 3663, "净化者德尔格伦", "灰谷", 26.2, 38.6, 1440 } }, e = { 5492, "纯洁的凯瑟琳", "暴风城", 37.4, 32, 1453 }, note = "这是连锁一步：先到奥萨拉克斯之塔(黑海岸 56,27)顶层从宝珠处接前置，做完后本任务才会出现。" },
    [78090] = { n = "A Second Opinion", cn = "另寻高见", l = 30, r = 22, f = "A", races = { 1, 3 }, s = { { 5492, "纯洁的凯瑟琳", "暴风城", 37.4, 32, 1453 } }, e = { 5495, "厄苏拉·德林", "暴风城", 26.2, 77.4, 1453 } },
    [78091] = { n = "Earning Your Salt", cn = "刻苦赚盐", l = 30, r = 22, f = "A", races = { 1, 3 }, s = { { 5495, "厄苏拉·德林", "暴风城", 26.2, 77.4, 1453 } }, e = { 5495, "厄苏拉·德林", "暴风城", 26.2, 77.4, 1453 }, note = "前置链从奥萨拉克斯之塔(黑海岸 56,27)顶层的宝珠接起；若 NPC 头顶没有问号，先回查前置是否完成。" },
    [78092] = { n = "It Must Be Destroyed", cn = "必毁无疑", l = 30, r = 22, f = "A", races = { 1, 3 }, s = { { 5495, "厄苏拉·德林", "暴风城", 26.2, 77.4, 1453 } }, e = { 409311, "玛诺洛斯的战矛", "灰谷", 89.4, 77.1, 1440 } },
    [78093] = { n = "Return to Delgren", cn = "向德尔格伦复命", l = 30, r = 22, f = "A", races = { 1, 3 }, s = { { 409315, "破碎的光球", "灰谷", 89.4, 77, 1440 } }, e = { 3663, "净化者德尔格伦", "灰谷", 26.2, 38.6, 1440 }, items = { 277205 } },
    [78261] = { n = "The Horn of Xelthos", cn = "谢尔索斯号角", l = 23, r = 1, s = { { 410369, "死信箱", "银松森林", 47.1, 71.1, 1421 } }, e = { 410369, "死信箱", "银松森林", 47.1, 71.1, 1421 }, note = "接取点在影牙城堡外焚木村旁屋内的死信箱(银松森林 47,71)；20 级来做建议把诡诈天赋点满（暗夜精灵自带加成则 1/3 即可），24 级或学会消失后无需点；打法：闷棍看守→扳动拉杆→潜行进牢笼最里侧对话，被打出潜行可用消失脱身；潜行不够时可以故意死掉，跑尸进笼对话后先别急着复活，等 NPC 开门再释放，笼门会保持敞开；开宝箱若报内部背包错误，钥匙会销毁且拿不到号角，只能放弃重接。" },
    [78270] = { n = "Goblin Lockpicks", cn = "地精的开锁工具", l = 23, r = 1, e = { 4086, "维尼克斯", "石爪山脉", 58.2, 51.6, 1442 }, items = { 210186 } },
    [78307] = { n = "The Horn of Xelthos", cn = "谢尔索斯号角", l = 23, r = 1, e = { 410369, "死信箱", "银松森林", 47.1, 71.1, 1421 }, items = { 277210, 203994 }, note = "完成本步后回死信箱(银松森林 47,71)取回后续信件；「C」的下一封邮件要先回一趟主城才会送达，别在原地傻等。" },
    [78676] = { n = "The Eye of Bhossca", cn = "波斯卡之眼", l = 35, r = 25, s = { { 410369, "死信箱", "银松森林", 47.1, 71.1, 1421 } }, e = { 410369, "死信箱", "银松森林", 47.1, 71.1, 1421 }, note = "30 级后收到「C」的邮件触发，接取点与《谢尔索斯号角》相同：焚木村旁死信箱(银松森林 47,71)；任务要进血色修道院，先进修道院外马厩(提瑞斯法林地 81,32)拿血色学徒制服伪装，全程伪装行动会轻松很多。" },
    [78699] = { n = "The Eye of Bhossca", cn = "波斯卡之眼", l = 35, r = 25, e = { 410369, "死信箱", "银松森林", 47.1, 71.1, 1421 }, items = { 277246, 210979 }, note = "戴伪装进墓地侧翼；石棺旁有精英看守时，绕到北侧陵墓后方隔墙用交互键开启可避开战斗；注意开完还要回死信箱、回主城收信、再回死信箱跑一个来回才算闭环。" },
    [79358] = { n = "Storm, Earth, and Fire", cn = "风暴、大地与火焰", l = 40, r = 30, s = { { 259023, "维里克·雷嗥", "阿拉希高地", 59.8, 27.6, 1417 } }, e = { 4722, "拉乌·峭壁信使", "千针石林", 46, 51.6, 1441 }, note = "38 级任务，四种怪分处四张地图：凄凉之地玛拉顿周边、尘泥沼泽东北鱼人、荒地中南部穴居人、悲伤沼泽中北部失落者；任务虽标部落但联盟同样可做；凄凉之地一处刷新很慢，建议把四张图串成一条路线。" },
