    [95036] = { n = "A Moon-Kissed Blade", cn = "月吻之刃", l = 25, r = 20, f = "H", races = { 5, 6 }, s = { { 259620, "露米娜·风语者", "银松森林", 43.2, 41, 1421 } }, e = { 248840, "特雷万·罗尔", "银松森林", 43.4, 41, 1421 }, note = "三样材料：白橡木——死亡矿井斯尼德房间的地精掉落（首杀基本必出）；附魔银锭——影牙城堡尽头阿鲁高身旁闪光的桌上直接拿（借别人打完的副本进度跑到底也行）；净化科尔宝石——先去佐拉姆海滩找乌尔里克·霜幕接《寻找科尔宝石》，再到黑暗深渊副本门前杀娜迦女祭司（约十只内出，并非必掉）。" },
    [95042] = { n = "Seeking the Kor Gem", cn = "寻找科尔宝石", l = 25, r = 20, f = "H", races = { 5 }, s = { { 259649, "乌尔里克·霜纱", "灰谷", 11.8, 34.4, 1440 } }, e = { 259649, "乌尔里克·霜纱", "灰谷", 11.8, 34.4, 1440 }, items = { 272448 }, note = "奥特在塔伦米尔东南角、部落货车旁；交任务后原地看他锻剑半分钟，随后接下一步。" },
    [95111] = { n = "An Underrated Talent", cn = "被低估的天赋", l = 25, r = 20, f = "H", races = { 5 }, s = { { 248840, "特雷万·罗尔", "银松森林", 43.4, 41, 1421 } }, e = { 3539, "奥特", "希尔斯布莱德丘陵", 60.4, 26, 1424 } },
    [95125] = { n = "Ott's Masterwork", cn = "奥特的杰作", l = 25, r = 20, f = "H", races = { 5 }, s = { { 3539, "奥特", "希尔斯布莱德丘陵", 60.4, 26, 1424 } }, e = { 3539, "奥特", "希尔斯布莱德丘陵", 60.4, 26, 1424 }, note = "纯等待环节：站在旁边看他把武器锻好即可。" },
    [95126] = { n = "The Moonsilver Blade", cn = "月银之刃", l = 25, r = 20, f = "H", races = { 5 }, s = { { 3539, "奥特", "希尔斯布莱德丘陵", 60.4, 26, 1424 } }, e = { 248840, "特雷万·罗尔", "银松森林", 43.4, 41, 1421 }, items = { 268484 }, note = "部落版 20 级圣骑士武器链（对应联盟的维里甘之拳）；到坟场地下室交剑，接着从身旁的卢米娜处接后续。" },
    [95140] = { n = "Old Fire-Eye", cn = "老火眼", l = 26, r = 20, f = "H", races = { 5 }, s = { { 259620, "露米娜·风语者", "银松森林", 43.2, 41, 1421 } }, e = { 259620, "露米娜·风语者", "银松森林", 43.2, 41, 1421 }, items = { 267369 }, note = "出发前先到战争区武器大师阿奇博尔德(57.1,32.5)处学双手剑，技能点要够打 25 级精英；老火眼在(48.8)一带巡逻，带深紫色护盾光环，装备月银之刃的第一次自动攻击会破盾（会出事件提示）；建议组队，25 级+110 双手剑技能也可单挑（圣印+惩击慢慢磨）。" },
    [95803] = { n = "A Token of Good Faith", cn = "诚意的信物", l = 12, r = 9, f = "H", races = { 5 }, s = { { 246378, "丹妮莎·莫尔", "提瑞斯法林地", 22, 44.6, 1420 } }, e = { 10181, "希尔瓦娜斯·风行者", "幽暗城", 57.8, 91.8, 1458 } },
    [96016] = { n = "The Tempest's Weapons", cn = "风暴武器", l = 40, r = 30, f = "A", s = { { 259023, "维里克·雷嗥", "阿拉希高地", 59.8, 27.6, 1417 } }, e = { 6176, "捕风者巴斯拉", "奥特兰克山脉", 80.4, 66.8, 1416 }, items = { 280696, 280607, 280605, 280604 }, note = "需求量很大：怪常被抢（组队又得分任务物品、掉率一般），PVP 服还有对面阵营长期对峙；虽然奖励不错，做好打持久战的准备。" },
    [96135] = { n = "Heed My Call", cn = "听从我的呼唤", l = 40, r = 30, f = "A", s = { { 259023, "维里克·雷嗥", "阿拉希高地", 59.8, 27.6, 1417 } }, e = { 259023, "维里克·雷嗥", "阿拉希高地", 59.8, 27.6, 1417 } },
    [96136] = { n = "Call of Air", cn = "空气的召唤", l = 35, r = 30, f = "H", races = { 96 }, items = { 5178 } },
    [96204] = { n = "The Windshaper's Wrath", cn = "塑风者之怒", l = 22, r = 18, f = "H", races = { 5 }, s = { { 248755, "露米娜·风语者", "银松森林", 65.7, 27.4, 1421 } }, e = { 259620, "露米娜·风语者", "银松森林", 43.2, 41, 1421 }, note = "开笼后是护送战：她沿战争区步行穿出城堡，到门口说完「快自由了」就跑向码头，快到码头时会自己回坟场，护送即告完成并接《债》；别离她太远，脱战或不跟丢都容易失败。" },
    [96243] = { n = "Call of Earth", cn = "大地的召唤", l = 10, r = 10, f = "A", s = { { 258098, "埃尔德伦·风暴破坏者", "铁炉堡", 47.4, 13.6, 1455 }, { 258113, "英格丽德·邓瓦尔德", "丹莫罗", 47.4, 52, 1426 } }, e = { 257446, "提欧·暴风之锤", "丹莫罗", 28.7, 66.1, 1426 } },
    [96264] = { n = "Elemental Aid", cn = "元素救兵", l = 33, r = 30, f = "A", s = { { 259023, "维里克·雷嗥", "阿拉希高地", 59.8, 27.6, 1417 } }, e = { 259023, "维里克·雷嗥", "阿拉希高地", 59.8, 27.6, 1417 } },
    [96779] = { n = "Syndicate Sabotage", cn = "破坏辛迪加", l = 24, r = 24, s = { { 13085, "麦洛克斯", "奥特兰克山脉", 85, 80.4, 1416 } }, e = { 13085, "麦洛克斯", "奥特兰克山脉", 85, 80.4, 1416 } },
    [96781] = { n = "What's the Big Idea?", cn = "有什么大阴谋？", l = 36, r = 24, s = { { 13085, "麦洛克斯", "奥特兰克山脉", 85, 80.4, 1416 } }, e = { 13085, "麦洛克斯", "奥特兰克山脉", 85, 80.4, 1416 }, note = "目标在斯坦恩布莱德的屋内(63,44)，对他偷窃即可；周边有潜行怪；低于他等级建议点满诡诈天赋，可用扰乱+消失兜底；29 级没带闪光粉会试很多次，建议 30 级再来做。" },
    [96782] = { n = "Covert Extraction", cn = "秘密取回", l = 36, r = 24, e = { 13085, "麦洛克斯", "奥特兰克山脉", 85, 80.4, 1416 }, note = "30 级点满诡诈会轻松很多；盾在塔内(41.4,40.2)，剑在(38.5,58)的塔内且周围精英环绕；物品本体旁边没有直接守卫，拿了就走；目前暂无后续任务。" },
    [96783] = { n = "A Way In", cn = "潜入之法", l = 34, r = 24, s = { { 13085, "麦洛克斯", "奥特兰克山脉", 85, 80.4, 1416 } }, e = { 656157, "辛迪加储物箱", "阿拉希高地", 32.4, 26.7, 1417 }, note = "目标物品在(阿拉希高地 32.3,26.6)。" },
    [96784] = { n = "Master of Disguise", cn = "伪装大师", l = 34, r = 24, s = { { 656157, "辛迪加储物箱", "阿拉希高地", 32.4, 26.7, 1417 } }, e = { 266847, "安娜斯塔西娅·米勒", "阿拉希高地", 26.8, 64.4, 1417 }, note = "安娜斯塔西娅·米勒在城堡外的岩架上(26.8,64.4)，从旁边房子跳上去就能到。" },
    [96785] = { n = "Ain't No Telling", cn = "无可奉告", l = 34, r = 24, s = { { 266847, "安娜斯塔西娅·米勒", "阿拉希高地", 26.8, 64.4, 1417 } }, e = { 266847, "安娜斯塔西娅·米勒", "阿拉希高地", 26.8, 64.4, 1417 }, note = "安娜斯塔西娅的藏匿处在城堡旁一栋房子的二楼(29.5,65.1)，拿到被窃资金后回去交还。" },
    [96786] = { n = "The Syndicate Sting", cn = "辛迪加诱捕行动", l = 34, r = 24, s = { { 266847, "安娜斯塔西娅·米勒", "阿拉希高地", 26.8, 64.4, 1417 } }, e = { 13085, "麦洛克斯", "奥特兰克山脉", 85, 80.4, 1416 }, note = "箱子在(阿拉希高地 15.5,43)，由两名 NPC 看守。" },
